def tool_example(name):
    label, desc, props, req = TOOL_DEFS[name]
    ex = {"action": name}
    for k, v in props.items():
        if k in req:
            ex[k] = 1 if v.get("type") in ("integer", "number") else "..."
    return json.dumps(ex, ensure_ascii=False)


def build_text_hint(names, tool_names=(), apps=""):
    comp = [n for n in TEXT_EXAMPLES if n in names]
    tl = [n for n in TOOL_DEFS if n in tool_names]
    first = '{"action": "screenshot"}' if comp else tool_example(tl[0])
    intro = ("У тебя есть доступ к экрану компьютера пользователя и к инструментам. " if comp and tl else
             "У тебя есть доступ к экрану компьютера пользователя. " if comp else "У тебя есть инструменты. ")
    lines = "\n".join("  " + TEXT_EXAMPLES[n] for n in comp)
    if tl:
        lines += ("\n" if lines else "") + "\n".join(
            "  " + tool_example(n) + "   — " + TOOL_DEFS[n][1].replace("{apps}", apps).split(". ")[0].rstrip(".")
            for n in tl)
    s = (intro + "Ты не можешь вызывать функции — вместо этого действия описываются текстом. Чтобы выполнить "
         "действие, ответь ОДНИМ коротким предложением (что делаешь) и сразу после него ОДНИМ блоком JSON, например:\n"
         + ("Смотрю на экран." if comp else "Ищу информацию.") + "\n```json\n" + first + "\n```\n"
         "Допустимые действия:\n" + lines + "\n  {\"action\": \"done\"}   (задача выполнена)\n"
         "Выполняй ОДНО действие за ответ. После него программа сама пришлёт результат. ")
    if comp:
        s += ("Сначала всегда делай скриншот; после действий программа присылает новый скриншот (красный круг — "
              "курсор). Координаты — в пикселях скриншота, кликай в центр нужного элемента. Чтобы запустить программу: "
              "нажми клавишу win, напечатай название, нажми enter. Чтобы ввести текст, сначала кликни в поле. ")
    s += ("Подтверждение действий запрашивает сама программа — НЕ проси пользователя ничего подтверждать и не пиши "
          "про кнопки. Если для ответа действия не нужны — просто ответь словами, без JSON. Когда задача выполнена "
          "или невозможна — ответь без JSON, коротко сообщив результат.")
    if comp:
        s += " Не вводи пароли и не делай необратимых действий без явной просьбы."
    return s


def extract_actions(text):
    """Достаёт JSON-действия из текста ответа. Возвращает (текст без действий, [dict])."""
    dec, acts, spans, i = json.JSONDecoder(), [], [], 0
    while True:
        i = text.find("{", i)
        if i < 0:
            break
        try:
            obj, end = dec.raw_decode(text, i)
        except ValueError:
            i += 1
            continue
        if isinstance(obj, dict) and "action" in obj:
            acts.append(obj)
            spans.append((i, end))
            i = end
        else:
            i += 1
    clean, pos = "", 0
    for a, b in spans:
        clean += text[pos:a]
        pos = b
    clean += text[pos:]
    clean = re.sub(r"```[A-Za-z]*", "", clean)
    clean = re.sub(r"\[\s*(,\s*)*\]", "", clean)
    return clean.strip(), acts


def normalize_action(a):
    """Приводит действие от модели к (имя_инструмента, аргументы); (None, {}) — не распознано."""
    if not isinstance(a, dict):
        return None, {}
    raw = str(a.get("action") or "").lower().strip().replace(" ", "_")
    name = ACTION_ALIASES.get(raw)
    if name is None and raw in TOOL_DEFS:
        name = raw
    args = {k: v for k, v in a.items() if k != "action"}
    if isinstance(args.get("arguments"), dict):
        args.update(args.pop("arguments"))
    if raw == "double_click":
        args.setdefault("clicks", 2)
    if raw == "right_click":
        args.setdefault("button", "right")
    for key in ("coordinate", "coordinates", "position", "point", "xy"):
        v = args.get(key)
        if isinstance(v, (list, tuple)) and len(v) == 2:
            args["x"], args["y"] = v
    for src, dst in (("from", ("x1", "y1")), ("to", ("x2", "y2")), ("start", ("x1", "y1")), ("end", ("x2", "y2"))):
        v = args.get(src)
        if isinstance(v, (list, tuple)) and len(v) == 2:
            args[dst[0]], args[dst[1]] = v
    if "key" in args and "keys" not in args:
        args["keys"] = args.pop("key")
    if isinstance(args.get("keys"), (list, tuple)):
        args["keys"] = "+".join(str(k) for k in args["keys"])
    if name == "type_text" and "text" not in args and "content" in args:
        args["text"] = args["content"]
    if name == "scroll" and "amount" not in args:
        d = str(args.get("direction", "down")).lower()
        args["amount"] = 3 if d == "up" else -3
    if name == "wait" and "seconds" not in args and "duration" in args:
        args["seconds"] = args["duration"]
    if name == "web_search" and "query" not in args:
        for k in ("q", "text", "keywords", "search", "request"):
            if k in args:
                args["query"] = args.pop(k)
                break
    if name in ("remember", "forget") and "text" not in args:
        for k in ("fact", "content", "query", "memory"):
            if k in args:
                args["text"] = args.pop(k)
                break
    return name, args


