def hex_mix(c1, c2, t):
    a = [int(c1[i:i + 2], 16) for i in (1, 3, 5)]
    b = [int(c2[i:i + 2], 16) for i in (1, 3, 5)]
    return "#%02x%02x%02x" % tuple(round(x + (y - x) * t) for x, y in zip(a, b))


# ----- сворачиваемые разделы: заголовок — кнопка, состояние запоминается в ui_state.json -----
_UI_STATE = {}
_UI_LOADED = [False]
_SECTIONS = []


def _ui_state():
    if not _UI_LOADED[0]:
        _UI_LOADED[0] = True
        d = load_json(BASE / "ui_state.json", {})
        if isinstance(d, dict) and isinstance(d.get("sections"), dict):
            _UI_STATE.update(d["sections"])
    return _UI_STATE


def _ui_save():
    try:
        save_json(BASE / "ui_state.json", {"sections": _UI_STATE})
    except OSError:
        pass


def _sec_alive(sec):
    try:
        return bool(sec["frame"].winfo_exists())
    except Exception:
        return False


def sec_set(sec, open_, save=True):
    """Свернуть или развернуть раздел: дочерние виджеты прячутся и возвращаются на место."""
    f = sec["frame"]
    if not _sec_alive(sec):
        return
    if open_ != sec["open"]:
        if open_:
            sp = sec.pop("spacer", None)      # распорка (pack) мешает grid-детям: убираем до возврата
            if sp is not None:
                try:
                    sp.destroy()
                except tk.TclError:
                    pass
            for c, mgr, info in sec["saved"]:
                try:
                    c.grid() if mgr == "grid" else c.pack(**info)
                except tk.TclError:
                    pass
            sec["saved"] = []
            f.configure(padding=(10, 6))
        else:
            saved = []
            for c in f.winfo_children():
                mgr = c.winfo_manager()
                if mgr == "grid":
                    c.grid_remove()
                    saved.append((c, mgr, None))
                elif mgr == "pack":
                    info = c.pack_info()
                    info.pop("in", None)
                    c.pack_forget()
                    saved.append((c, mgr, info))
            sec["saved"] = saved
            sp = ttk.Frame(f, height=6)
            sp.pack(fill="x")
            sec["spacer"] = sp
            f.configure(padding=(10, 0, 10, 3))
        sec["open"] = open_
    f.configure(text=("▾ " if open_ else "▸ ") + sec["title"])
    if save:
        _ui_state()[sec["title"]] = bool(open_)
        _ui_save()


def LabelFrame(parent, text, open=False):
    """Раздел с рамкой; клик по заголовку сворачивает и разворачивает его. open — состояние по умолчанию."""
    want = bool(_ui_state().get(text, open))
    f = ttk.LabelFrame(parent, text=("▾ " if want else "▸ ") + text, padding=(10, 6))
    sec = {"title": text, "open": True, "saved": [], "frame": f}
    f._sec = sec
    _SECTIONS[:] = [x for x in _SECTIONS if _sec_alive(x)] + [sec]
    f.bind("<Button-1>", lambda e, s=sec: sec_set(s, not s["open"]) if e.y <= 26 else None)
    f.bind("<Motion>", lambda e, w=f: w.configure(cursor="hand2" if e.y <= 26 else ""))
    if not want:
        f.after_idle(lambda: sec_set(sec, False, save=False))
    return f


def section_toolbar(parent):
    """Кнопки «Развернуть все / Свернуть все» над разделами страницы."""
    bar = ttk.Frame(parent)
    bar.pack(fill="x", padx=8, pady=(2, 0))

    def all_(state):
        for sec in list(_SECTIONS):
            if _sec_alive(sec) and sec["frame"].master is parent:
                sec_set(sec, state)
    ttk.Button(bar, text="⊞ Развернуть все", command=lambda: all_(True)).pack(side="left", padx=(0, 6))
    ttk.Button(bar, text="⊟ Свернуть все", command=lambda: all_(False)).pack(side="left")
    ttk.Label(bar, text="Нажмите на заголовок раздела, чтобы открыть или скрыть его", foreground="#888888").pack(
        side="left", padx=12)
    return bar


class ScrollFrame:
    """Вертикально прокручиваемая область; виджеты кладём в .inner (колесо мыши работает над областью)."""

    def __init__(self, parent):
        self.cv = tk.Canvas(parent, highlightthickness=0, bd=0)
        self.sb = ttk.Scrollbar(parent, orient="vertical", command=self.cv.yview)
        self.cv.configure(yscrollcommand=self.sb.set)
        self.sb.pack(side="right", fill="y")
        self.cv.pack(side="left", fill="both", expand=True)
        self.inner = ttk.Frame(self.cv)
        self._win = self.cv.create_window((0, 0), window=self.inner, anchor="nw")
        self.inner.bind("<Configure>", lambda e: self.cv.configure(scrollregion=self.cv.bbox("all")))
        self.cv.bind("<Configure>", lambda e: self.cv.itemconfigure(self._win, width=e.width))
        self.cv.bind_all("<MouseWheel>", self._wheel, add="+")

    def _wheel(self, e):
        try:
            w = self.cv.winfo_containing(e.x_root, e.y_root)
            while w is not None and w is not self.inner and w is not self.cv:
                w = w.master
            if w is None or self.cv.yview() == (0.0, 1.0):
                return
            self.cv.yview_scroll(-1 if e.delta > 0 else 1, "units")
        except Exception:
            pass


# ------------------------------------ утилиты ------------------------------------
def add_nvidia_dll_dirs():
    """Подключает DLL из pip-пакетов nvidia-cublas-cu12 / nvidia-cudnn-cu12 (Windows)."""
    if not hasattr(os, "add_dll_directory"):
        return
    try:
        import site
        roots = set(site.getsitepackages() + [site.getusersitepackages()] + [x for x in sys.path if x])
    except Exception:
        roots = {x for x in sys.path if x}
    if getattr(sys, "frozen", False):   # собранный exe: библиотеки лежат рядом или в _internal
        roots |= {str(x) for x in (getattr(sys, "_MEIPASS", None), Path(sys.executable).parent,
                                   Path(sys.executable).parent / "_internal") if x}
    for root in roots:
        base = Path(root) / "nvidia"
        if base.is_dir():
            for bin_dir in base.glob("*/bin"):
                try:
                    os.add_dll_directory(str(bin_dir))
                    os.environ["PATH"] = str(bin_dir) + os.pathsep + os.environ.get("PATH", "")
                except OSError:
                    pass


add_nvidia_dll_dirs()


def load_json(path, default):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


_JSON_LOCK = threading.RLock()


def save_json(path, data):
    """Атомарная запись: сначала во временный файл рядом, потом замена. Читатель никогда не увидит половину файла,
    а два потока не склеят содержимое (раньше так можно было испортить настройки плагина)."""
    path = Path(path)
    tmp = path.with_name(f".{path.name}.{os.getpid()}.{threading.get_ident()}.tmp")
    try:
        tmp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        for i in range(6):
            try:
                os.replace(tmp, path)
                break
            except PermissionError:            # Windows: файл в этот миг читает другой поток
                if i == 5:
                    raise
                time.sleep(0.05)
    finally:
        try:
            tmp.unlink()
        except OSError:
            pass


