def comp_activate():
    """Подключает докачанные компоненты: папки в sys.path (после встроенных) и DLL NVIDIA."""
    try:
        dirs = [d for d in sorted(COMP_DIR.iterdir()) if d.is_dir() and not d.name.startswith(".")]
    except OSError:
        return
    for d in dirs:
        if str(d) not in sys.path:
            sys.path.append(str(d))
    add_nvidia_dll_dirs()


def comp_installed():
    d = load_json(COMP_FILE, {})
    return d if isinstance(d, dict) else {}


def _mod_present(mod):
    import importlib.util
    try:
        return importlib.util.find_spec(mod) is not None
    except (ImportError, ValueError, AttributeError):
        return False


def comp_status(c):
    """("installed"|"builtin"|"none", текст)."""
    rec = comp_installed().get(c["id"])
    if rec and (COMP_DIR / c["id"]).is_dir():
        return "installed", "загружен: " + ", ".join(f"{k} {v}" for k, v in rec.get("pkgs", {}).items())
    if _mod_present(c["mod"]):
        return "builtin", "уже есть в программе"
    return "none", "не загружен"


def _wheel_ok(filename):
    """Подходит ли wheel этому Python и системе (без пакетов, которые нужно собирать)."""
    parts = filename[:-4].split("-")
    if len(parts) < 5:
        return False
    py, abi, plat = parts[-3].split("."), parts[-2].split("."), parts[-1].split(".")
    cur = f"cp{sys.version_info[0]}{sys.version_info[1]}"

    def plat_ok(p):
        if p == "any":
            return True
        if sys.platform == "win32":
            return p == "win_amd64"
        if sys.platform.startswith("linux"):
            return p.startswith(("manylinux", "linux_x86_64"))
        return False
    if not any(plat_ok(p) for p in plat):
        return False
    if any(t.startswith("py3") for t in py):
        return True
    return any(t == cur and any(a in (cur, "abi3", "none") for a in abi) for t in py)


def _marker_ok(marker):
    """Грубая проверка условия зависимости (python_version, платформа). Сложные условия — «подходит»."""
    import platform
    if not marker:
        return True
    if re.search(r"\bextra\b", marker):
        return False
    if "(" in marker:
        return True
    env = {"python_version": f"{sys.version_info[0]}.{sys.version_info[1]}",
           "sys_platform": sys.platform, "os_name": os.name, "implementation_name": "cpython",
           "platform_system": {"win32": "Windows", "linux": "Linux", "darwin": "Darwin"}.get(sys.platform, ""),
           "platform_machine": "AMD64" if sys.platform == "win32" else platform.machine()}

    def ver(x):
        return tuple(int(p) for p in re.findall(r"\d+", x))
    try:
        for orp in re.split(r"\s+or\s+", marker):
            ok = True
            for term in re.split(r"\s+and\s+", orp):
                m = re.match(r"""^\s*([a-z_]+)\s*(==|!=|<=|>=|<|>|not in|in)\s*['"]([^'"]*)['"]\s*$""", term)
                if not m or m.group(1) not in env:
                    raise ValueError(term)
                k, op, val = m.groups()
                have = env[k]
                if k == "python_version":
                    a, b = ver(have), ver(val)
                    r = {"==": a == b, "!=": a != b, "<": a < b, "<=": a <= b, ">": a > b, ">=": a >= b}.get(op)
                else:
                    r = {"==": have == val, "!=": have != val, "in": have in val, "not in": have not in val}.get(op)
                if r is None:
                    raise ValueError(term)
                ok = ok and r
            if ok:
                return True
        return False
    except ValueError:
        return True


def pypi_info(name, session=None):
    """(версия, файл wheel, [условия зависимостей]) последнего подходящего wheel с PyPI."""
    get = (session or requests).get
    r = get(f"{PYPI_API}/{name}/json", timeout=30)
    if r.status_code == 404:
        raise RuntimeError(f"пакет {name} не найден на PyPI")
    r.raise_for_status()
    d = r.json()
    cands = [f for f in d.get("urls", []) if f.get("packagetype") == "bdist_wheel" and not f.get("yanked")
             and _wheel_ok(f["filename"])]
    if not cands:
        raise RuntimeError(f"для {name} нет подходящей сборки под вашу систему")
    cands.sort(key=lambda f: (0 if f["filename"].endswith("-any.whl") else 1, f["filename"]))
    return d["info"]["version"], cands[0], list(d["info"].get("requires_dist") or [])


def pypi_pick(name, session=None):
    ver, f, _ = pypi_info(name, session)
    return ver, f


def _safe_extract(zf, target):
    target = Path(target).resolve()
    for m in zf.infolist():
        dest = (target / m.filename).resolve()
        if dest != target and target not in dest.parents:
            raise RuntimeError(f"небезопасный путь в архиве: {m.filename}")
    for m in zf.infolist():
        if m.filename.replace("\\", "/").split("/")[0].endswith(".data"):
            continue            # скрипты и прочее из .data не нужны
        zf.extract(m, target)


def comp_download(c, progress=None, cancel=None):
    """Скачивает и распаковывает все пакеты компонента в components/<id>. progress(done, total, text)."""
    import hashlib
    import zipfile
    if c.get("windows_only") and sys.platform != "win32":
        raise RuntimeError("этот компонент нужен только в Windows")
    COMP_DIR.mkdir(parents=True, exist_ok=True)
    tmp = COMP_DIR / ".tmp"
    tmp.mkdir(exist_ok=True)
    target = COMP_DIR / (c["id"] + ".new")
    if target.exists():
        shutil.rmtree(target, ignore_errors=True)
    target.mkdir()
    got = {}
    try:
        plan, seen, queue = [], set(), list(c["pkgs"])
        while queue:
            name = queue.pop(0)
            key = re.sub(r"[-_.]+", "-", name).lower()
            if key in seen:
                continue
            seen.add(key)
            if len(seen) > 40:
                raise RuntimeError("слишком много зависимостей — остановлено")
            if progress:
                progress(0, 0, f"ищу {name}…")
            ver, f, req = pypi_info(name)
            plan.append((name, ver, f))
            if c.get("resolve"):
                for line in req:
                    spec, _, marker = line.partition(";")
                    mm = re.match(r"^\s*([A-Za-z0-9][A-Za-z0-9_.-]*)", spec)
                    if mm and _marker_ok(marker.strip()):
                        queue.append(mm.group(1))
        total = sum(int(f.get("size") or 0) for _, _, f in plan)
        done = 0
        for name, ver, f in plan:
            url = f["url"]
            u = urlparse(url)
            if (u.scheme != "https" and not PYPI_ALLOW_HTTP) or u.hostname not in PYPI_FILE_HOSTS:
                raise RuntimeError(f"неожиданный адрес загрузки: {u.hostname}")
            path = tmp / f["filename"]
            h = hashlib.sha256()
            with requests.get(url, stream=True, timeout=(15, 60)) as r, open(path, "wb") as out:
                r.raise_for_status()
                for chunk in r.iter_content(1 << 20):
                    if cancel and cancel():
                        raise RuntimeError("отменено")
                    out.write(chunk)
                    h.update(chunk)
                    done += len(chunk)
                    if progress:
                        progress(done, total, f"{name} {ver}")
            want = (f.get("digests") or {}).get("sha256")
            if not want or h.hexdigest() != want:
                raise RuntimeError(f"контрольная сумма {name} не совпала — файл не используется")
            with zipfile.ZipFile(path) as zf:
                _safe_extract(zf, target)
            path.unlink(missing_ok=True)
            got[name] = ver
        final = COMP_DIR / c["id"]
        if final.exists():
            shutil.rmtree(final)
        target.rename(final)
        rec = comp_installed()
        rec[c["id"]] = {"pkgs": got, "time": datetime.now().strftime("%Y-%m-%d %H:%M")}
        save_json(COMP_FILE, rec)
    except BaseException:
        shutil.rmtree(target, ignore_errors=True)
        raise
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    comp_activate()
    return got


def comp_remove(c):
    shutil.rmtree(COMP_DIR / c["id"], ignore_errors=True)
    rec = comp_installed()
    if rec.pop(c["id"], None) is not None:
        save_json(COMP_FILE, rec)


