def clean_for_tts(text: str) -> str:
    text = re.sub(r"<think>.*?</think>", "", text, flags=re.S)
    text = re.sub(r"```.*?```", " ", text, flags=re.S)
    text = re.sub(r"[*_#`>]+", "", text)
    return re.sub(r"\s+", " ", text).strip()


class ThinkFilter:
    """Вырезает <think>...</think> из потока, даже если тег разорван между кусками."""
    OPEN, CLOSE = "<think>", "</think>"

    def __init__(self):
        self.buf = ""
        self.inside = False

    def feed(self, s):
        self.buf += s
        out = ""
        while True:
            if self.inside:
                i = self.buf.find(self.CLOSE)
                if i < 0:
                    self.buf = self.buf[-(len(self.CLOSE) - 1):]
                    return out
                self.buf = self.buf[i + len(self.CLOSE):]
                self.inside = False
            else:
                i = self.buf.find(self.OPEN)
                if i < 0:
                    keep = 0
                    for k in range(min(len(self.OPEN) - 1, len(self.buf)), 0, -1):
                        if self.OPEN.startswith(self.buf[-k:]):
                            keep = k
                            break
                    out += self.buf[:len(self.buf) - keep]
                    self.buf = self.buf[len(self.buf) - keep:]
                    return out
                out += self.buf[:i]
                self.buf = self.buf[i + len(self.OPEN):]
                self.inside = True

    def flush(self):
        out = "" if self.inside else self.buf
        self.buf = ""
        return out


BOUNDARY = re.compile(r'[.!?…]+["»”)\]]*\s+|\n+')


class Chunker:
    """Режет поток текста на фрагменты по границам предложений (не короче min_len символов)."""

    SOFT = re.compile(r"[,;:]\s+|\s[—–-]\s")

    def __init__(self, min_len=25, first_min=0):
        self.buf = ""
        self.pending = ""
        self.min_len = min_len
        self.first_min = first_min     # >0: самый первый фрагмент можно отрезать по запятой
        self.sent = False

    def feed(self, text):
        self.buf += text
        out = []
        while True:
            m = BOUNDARY.search(self.buf)
            if not m:
                break
            self.pending += self.buf[:m.end()]
            self.buf = self.buf[m.end():]
            if len(self.pending.strip()) >= self.min_len:
                out.append(self.pending.strip())
                self.pending = ""
                self.sent = True
        if self.first_min and not self.sent and not out:
            whole = self.pending + self.buf
            for m in self.SOFT.finditer(whole):
                if len(whole[:m.end()].strip()) >= self.first_min:
                    out.append(whole[:m.end()].strip())
                    self.pending, self.buf = "", whole[m.end():]
                    self.sent = True
                    break
        return out

    def flush(self):
        rest = (self.pending + self.buf).strip()
        self.pending = self.buf = ""
        self.sent = True
        return [rest] if rest else []


def screen_metrics():
    """(ширина, высота) основного экрана и позиция курсора в координатах мыши (Windows); иначе (None, None)."""
    try:
        import ctypes
        import ctypes.wintypes
        u = ctypes.windll.user32
        pt = ctypes.wintypes.POINT()
        u.GetCursorPos(ctypes.byref(pt))
        return (u.GetSystemMetrics(0), u.GetSystemMetrics(1)), (pt.x, pt.y)
    except Exception:
        return None, None


def gpu_stats():
    """Первая GPU NVIDIA: util %, VRAM ГБ, температура. None, если нет."""
    if NVML:
        try:
            h = pynvml.nvmlDeviceGetHandleByIndex(0)
            u = pynvml.nvmlDeviceGetUtilizationRates(h)
            m = pynvml.nvmlDeviceGetMemoryInfo(h)
            t = pynvml.nvmlDeviceGetTemperature(h, pynvml.NVML_TEMPERATURE_GPU)
            name = pynvml.nvmlDeviceGetName(h)
            if isinstance(name, bytes):
                name = name.decode()
            return dict(util=u.gpu, used=m.used / 2**30, total=m.total / 2**30, temp=t, name=name)
        except Exception:
            pass
    if shutil.which("nvidia-smi"):
        try:
            out = subprocess.check_output(
                ["nvidia-smi", "--query-gpu=name,utilization.gpu,memory.used,memory.total,temperature.gpu",
                 "--format=csv,noheader,nounits"], timeout=3, text=True,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0)).splitlines()[0]
            name, util, used, total, temp = [x.strip() for x in out.split(",")]
            return dict(util=float(util), used=float(used) / 1024, total=float(total) / 1024,
                        temp=float(temp), name=name)
        except Exception:
            pass
    return None


