BRAIN_JS = r'''const STATE_COLOR = {idle:'#8c96a3', listening:'#35d07f', thinking:'#ffc107', working:'#ff9800', speaking:'#4dabf7', sleeping:'#4a5260'};
const BASE_E = {curve:.35, brow:0, inner:0, eye:1, squint:0, blush:.25, happy:0, sad:0, angry:0, surprised:0,
                relaxed:0, blink:0, open:0, tilt:0, nod:0, gazeX:0, gazeY:0};
const EMO = {
  neutral: {},
  happy: {curve:1, squint:1, blush:.85, happy:.9, open:.12, brow:-.3},
  sad: {curve:-.9, eye:.8, blush:.05, sad:.85, brow:.3, inner:-.8, nod:.08},
  angry: {curve:-.55, eye:.75, blush:0, angry:.85, brow:.3, inner:.8},
  surprised: {curve:0, eye:1.2, surprised:.9, open:.7, brow:-1},
  thinking: {curve:.1, eye:.9, relaxed:.3, tilt:.12, gazeX:.5, gazeY:.5, brow:-.2},
  sleepy: {curve:.2, eye:.15, blink:1, nod:.28, blush:.3},
  listening: {curve:.55, eye:1.12, relaxed:.25, happy:.2, nod:-.04, brow:-.5, blush:.35},
};
function emoTarget(name) { return Object.assign({}, BASE_E, EMO[name] || {}); }

function makeBrain() {
  const B = {
    state: 'idle', emotion: 'neutral', emoUntil: 0, follow: null, bubble: '', bubbleUntil: 0,
    env: null, vis: null, speakT0: 0, speakUntil: 0, lastEvent: 0, sleepMin: 5, DT: 0.04, gest: null,
    phrases: ['Ой!', 'Хи-хи', 'Щекотно!', 'Я здесь!', 'Привет!'],
    handle(m, now) {
      if (!m || m.t === 'config') return;
      if (m.t === 'state' && m.state === 'sleeping') { B.state = 'sleeping'; return; }
      if (B.state === 'sleeping' && m.t === 'state' && m.state === 'idle') return;
      if (B.state === 'sleeping') {
        B.state = 'idle'; B.emotion = 'surprised'; B.emoUntil = now + .7;
      }
      B.lastEvent = now;
      if (m.t === 'gesture') { B.gest = {name: m.name, t0: now, dur: Number(m.secs) || 1.6}; return; }
      if (m.t === 'state') B.state = m.state;
      else if (m.t === 'emotion') { B.emotion = m.name; B.emoUntil = now + (m.secs || 4); }
      else if (m.t === 'bubble') { B.bubble = m.text || ''; B.bubbleUntil = now + (m.secs || 4); }
      else if (m.t === 'speak') {
        const dur = Number(m.dur) || 1;
        B.state = 'speaking'; B.env = m.env || null; B.vis = m.vis || null; B.speakT0 = now; B.speakUntil = now + dur + .1;
        B.emotion = m.emotion || 'neutral'; B.emoUntil = now + dur + 1.2;
        B.bubble = m.text || ''; B.bubbleUntil = now + dur + 2;
      }
    },
    poke(now) {
      if (B.state === 'sleeping') B.state = 'idle';
      B.lastEvent = now; B.emotion = 'surprised'; B.emoUntil = now + .6;
      B.follow = {at: now + .6, name: 'happy', secs: 1.8};
      B.bubble = B.phrases[Math.floor(Math.random() * B.phrases.length)]; B.bubbleUntil = now + 2.2;
    },
    step(now) {
      if (B.state === 'idle' && B.sleepMin > 0 && now - B.lastEvent > B.sleepMin * 60) B.state = 'sleeping';
      if (B.state === 'speaking' && now > B.speakUntil) B.state = 'idle';
      if (B.follow && now >= B.follow.at) {
        B.emotion = B.follow.name; B.emoUntil = now + B.follow.secs; B.follow = null;
      }
      const byState = {listening: 'listening', thinking: 'thinking', working: 'thinking', sleeping: 'sleepy'};
      const emo = now < B.emoUntil ? B.emotion : (byState[B.state] || 'neutral');
      let mouth = 0, vis = null;
      if (B.state === 'speaking') {
        if (B.env && B.env.length) {
          const i = Math.floor((now - B.speakT0) / B.DT);
          mouth = i >= 0 && i < B.env.length ? B.env[i] : 0;
          if (B.vis && i >= 0 && i < B.vis.length) vis = B.vis[i];
        } else mouth = Math.abs(Math.sin(now * 11)) * .8;
      }
      mouth = mouth < .08 ? 0 : Math.min(1, mouth) * .95;
      let gesture = null;
      if (B.gest && now < B.gest.t0 + B.gest.dur) {
        const p = (now - B.gest.t0) / B.gest.dur;
        gesture = {name: B.gest.name, t: now - B.gest.t0, env: Math.sin(Math.PI * Math.min(1, p))};
      } else {
        B.gest = null;
        if (B.state === 'working') gesture = {name: 'type', t: now, env: 1};
      }
      return {state: B.state, emo, target: emoTarget(emo), mouth, vis, gesture,
              bubble: now < B.bubbleUntil ? B.bubble : ''};
    },
  };
  return B;
}
'''

RENDER_JS = r'''const el = id => document.getElementById(id);
const query = new URLSearchParams(location.search);
const brain = makeBrain();
const now = () => performance.now() / 1000;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const cfg = {model: '', bg: '#1e1e1e', zoom: 1, arm: 1.1, track: true, bubble: true, sleep: 5, color: '#7aa2f7'};
window.__brain = brain;

function showMsg(t) { const m = el('msg'); m.textContent = t || ''; m.style.display = t ? 'block' : 'none'; }
function applyBg() { document.body.style.background = query.get('bg') || cfg.bg; }

let THREE = null;
try { THREE = await import('three'); }
catch (e) { showMsg('Не удалось загрузить three.js (' + (e && e.message || e) + '). Нужен интернет или локальные библиотеки — см. avatar3d/README.txt'); }

let renderer = null, scene = null, camera = null, lookTarget = null, avatar = null, loadId = 0, modelReady = false;
const mouse = {x: 0, y: 0};
const cur = emoTarget('neutral');
let nextBlink = now() + 3, blinkT0 = null, blinkVal = 0, saccade = {x: 0, y: 0, until: 0};

if (THREE) {
  try {
    renderer = new THREE.WebGLRenderer({canvas: el('c'), alpha: true, antialias: true});
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(30, 1, 0.05, 50);
    const sun = new THREE.DirectionalLight(0xffffff, 2.4); sun.position.set(1, 1.6, 2); scene.add(sun);
    scene.add(new THREE.AmbientLight(0xffffff, 1.0));
    lookTarget = new THREE.Object3D(); scene.add(lookTarget);
  } catch (e) { renderer = null; showMsg('WebGL недоступен: ' + (e && e.message || e)); }
}
function resize() {
  if (!renderer) return;
  const w = window.innerWidth, h = window.innerHeight;
  renderer.setSize(w, h, false); camera.aspect = w / Math.max(1, h); camera.updateProjectionMatrix();
}
window.addEventListener('resize', resize); resize();
window.addEventListener('pointermove', e => {
  mouse.x = (e.clientX / window.innerWidth) * 2 - 1; mouse.y = -((e.clientY / window.innerHeight) * 2 - 1);
});
el('c').addEventListener('click', () => brain.poke(now()));

// ---------- загрузка моделей ----------
let VRMLib = null;
async function loadLibs() {
  if (VRMLib) return VRMLib;
  const g = await import('three/addons/loaders/GLTFLoader.js');
  const v = await import('@pixiv/three-vrm');
  VRMLib = {GLTFLoader: g.GLTFLoader, VRMLoaderPlugin: v.VRMLoaderPlugin, VRMUtils: v.VRMUtils};
  return VRMLib;
}

function makeRobot() {
  const root = new THREE.Group();
  const col = new THREE.Color(cfg.color);
  const mat = (c, o) => new THREE.MeshStandardMaterial(Object.assign({color: c, roughness: .5, metalness: .05}, o || {}));
  const dark = col.clone().multiplyScalar(.45), bodyC = col.clone().multiplyScalar(.85);
  const body = new THREE.Mesh(new THREE.SphereGeometry(.55, 32, 24), mat(bodyC));
  body.scale.set(1.15, .8, .8); body.position.y = -.95; root.add(body);
  const head = new THREE.Group(); root.add(head);
  head.add(new THREE.Mesh(new THREE.SphereGeometry(.5, 40, 30), mat(col)));
  const eyes = [], pupils = [], brows = [], cheeks = [];
  for (const s of [-1, 1]) {
    const white = new THREE.Mesh(new THREE.SphereGeometry(.1, 20, 16), mat(0xffffff, {roughness: .3}));
    white.scale.set(1, 1.25, .55); white.position.set(s * .19, .08, .42); head.add(white); eyes.push(white);
    const pupil = new THREE.Mesh(new THREE.SphereGeometry(.05, 16, 12), mat(0x1d2b44));
    pupil.position.set(s * .19, .08, .46); head.add(pupil); pupils.push(pupil);
    const brow = new THREE.Mesh(new THREE.BoxGeometry(.17, .028, .02), mat(0x22263a));
    brow.position.set(s * .19, .27, .46); head.add(brow); brows.push(brow);
    const cheek = new THREE.Mesh(new THREE.SphereGeometry(.06, 12, 10), new THREE.MeshBasicMaterial({color: 0xff6f91, transparent: true, opacity: .3}));
    cheek.scale.set(1.2, .6, .3); cheek.position.set(s * .31, -.05, .4); head.add(cheek); cheeks.push(cheek);
    const ear = new THREE.Mesh(new THREE.SphereGeometry(.12, 16, 12), mat(dark));
    ear.scale.set(.5, 1, .8); ear.position.set(s * .5, 0, 0); head.add(ear);
  }
  const arms = [];
  for (const s of [-1, 1]) {
    const g = new THREE.Group(); g.position.set(s * .66, -.78, 0);
    const limb = new THREE.Mesh(new THREE.CylinderGeometry(.07, .07, .5, 12), mat(bodyC)); limb.position.y = -.25; g.add(limb);
    const hand = new THREE.Mesh(new THREE.SphereGeometry(.1, 16, 12), mat(col)); hand.position.y = -.52; g.add(hand);
    g.rotation.z = s * .12; root.add(g); arms.push(g);
  }
  const arc = new THREE.Mesh(new THREE.TorusGeometry(.09, .013, 8, 24, Math.PI), mat(0x22263a));
  arc.position.set(0, -.12, .47); head.add(arc);
  const mouthO = new THREE.Mesh(new THREE.SphereGeometry(.08, 20, 14), mat(0x5b1f2e));
  mouthO.position.set(0, -.17, .46); mouthO.visible = false; head.add(mouthO);
  const stem = new THREE.Mesh(new THREE.CylinderGeometry(.012, .012, .22, 8), mat(dark));
  stem.position.set(0, .6, 0); head.add(stem);
  const ball = new THREE.Mesh(new THREE.SphereGeometry(.06, 16, 12), mat(0x8c96a3, {emissive: new THREE.Color(0x8c96a3), emissiveIntensity: .6}));
  ball.position.set(0, .74, 0); head.add(ball);
  return {kind: 'robot', root, head, eyes, pupils, brows, cheeks, arc, mouthO, ball, armL: arms[0], armR: arms[1], frame: {cy: -.25, half: 1.2}};
}

function makeVrm(vrm) {
  const H = vrm.humanoid;
  const bone = n => { try { return H ? H.getNormalizedBoneNode(n) : null; } catch (e) { return null; } };
  if (vrm.lookAt) vrm.lookAt.target = lookTarget;
  const box = new THREE.Box3().setFromObject(vrm.scene), size = box.getSize(new THREE.Vector3());
  return {kind: 'vrm', root: vrm.scene, vrm, frame: {cy: box.min.y + size.y * .78, half: Math.max(.2, size.y * .27)},
          b: {armL: bone('leftUpperArm'), armR: bone('rightUpperArm'), neck: bone('neck'), chest: bone('chest'), spine: bone('spine')}};
}

function makeStatic(sceneObj) {
  const box = new THREE.Box3().setFromObject(sceneObj), size = box.getSize(new THREE.Vector3());
  return {kind: 'static', root: sceneObj, frame: {cy: (box.min.y + box.max.y) / 2, half: Math.max(.2, size.y * .55)}};
}

async function setModel(name) {
  const id = ++loadId;
  if (!renderer) return;
  if (avatar) { scene.remove(avatar.root); avatar = null; }
  showMsg('');
  let a = null;
  if (name) {
    try {
      showMsg('Загружаю модель…');
      const L = await loadLibs();
      const loader = new L.GLTFLoader();
      loader.register(p => new L.VRMLoaderPlugin(p));
      const gltf = await loader.loadAsync('/model/' + encodeURIComponent(name));
      if (id !== loadId) return;
      const vrm = gltf.userData && gltf.userData.vrm;
      if (vrm) { L.VRMUtils.rotateVRM0(vrm); a = makeVrm(vrm); } else a = makeStatic(gltf.scene);
      showMsg('');
    } catch (e) {
      if (id !== loadId) return;
      showMsg('Не удалось загрузить модель: ' + (e && e.message || e) + ' — показываю встроенного робота');
    }
  }
  if (!a) a = makeRobot();
  if (id !== loadId) return;
  avatar = a; scene.add(a.root);
  window.__avatarKind = a.kind;
}

// ---------- кадр ----------
function placeCamera() {
  if (!avatar) return;
  const f = avatar.frame;
  const dist = (f.half / Math.max(.2, cfg.zoom)) / Math.tan(camera.fov * Math.PI / 360);
  camera.position.set(0, f.cy, dist); camera.lookAt(0, f.cy, 0);
}

function gazeOffset(S, t) {
  if (S.target.gazeX || S.target.gazeY) return [S.target.gazeX * .5, S.target.gazeY * .4];
  if (S.state === 'working') return [Math.sin(t * 2.4) * .4, 0];
  if (cfg.track && S.state !== 'sleeping') return [mouse.x * .8, mouse.y * .4];
  if (t > saccade.until) saccade = {x: (Math.random() - .5) * .3, y: (Math.random() - .5) * .2, until: t + 2 + Math.random() * 3};
  return [saccade.x, saccade.y];
}

function updateVrm(a, S, dt, t, g) {
  const em = a.vrm.expressionManager;
  const set = (n, v) => { if (em) { try { em.setValue(n, clamp(v, 0, 1)); } catch (e) {} } };
  set('happy', cur.happy); set('sad', cur.sad); set('angry', cur.angry);
  set('surprised', cur.surprised); set('relaxed', cur.relaxed);
  set('blink', Math.max(cur.blink, blinkVal));
  const vs = a.vs || (a.vs = [0, 0, 0, 0, 0]), kv = Math.min(1, dt * 18);
  if (S.vis) {
    ['aa', 'ih', 'ou', 'ee', 'oh'].forEach((n, i) => { vs[i] += (S.vis[i] - vs[i]) * kv; set(n, vs[i]); });
  } else {
    set('aa', S.mouth * .9); set('oh', S.mouth * .25 * (.5 + .5 * Math.sin(t * 9)));
    ['ih', 'ou', 'ee'].forEach(n => set(n, 0)); vs.fill(0);
  }
  const k = Math.min(1, dt * 6), b = a.b;
  const rz = (bone, target) => { if (bone) bone.rotation.z += (target - bone.rotation.z) * k; };
  const G = S.gesture, ge = G ? G.env : 0;
  let aL = -cfg.arm, aR = cfg.arm, gNod = 0, gYaw = 0, gBow = 0;
  if (G) {
    if (G.name === 'wave') aR = cfg.arm + (-.8 + Math.sin(G.t * 11) * .22 - cfg.arm) * ge;
    else if (G.name === 'type') { aL = -cfg.arm * .55 + Math.sin(G.t * 13) * .07; aR = cfg.arm * .55 + Math.sin(G.t * 13 + 3) * .07; }
    else if (G.name === 'nod') gNod = Math.sin(G.t * 10) * .14 * ge;
    else if (G.name === 'shake') gYaw = Math.sin(G.t * 11) * .35 * ge;
    else if (G.name === 'bow') gBow = .38 * ge;
  }
  rz(b.armL, aL); rz(b.armR, aR);
  if (b.chest) b.chest.rotation.x = Math.sin(t * 1.6) * .012;
  if (b.spine) { b.spine.rotation.y = Math.sin(t * .5) * .02; b.spine.rotation.x += (gBow - b.spine.rotation.x) * k; }
  if (b.neck) {
    const nod = cur.nod + gNod + (S.state === 'speaking' ? Math.sin(t * 2.3) * .03 : 0);
    b.neck.rotation.x += (nod - b.neck.rotation.x) * k;
    b.neck.rotation.y += (gYaw - b.neck.rotation.y) * k;
    b.neck.rotation.z += (cur.tilt - b.neck.rotation.z) * k;
  }
  lookTarget.position.set(camera.position.x + g[0], camera.position.y + g[1], camera.position.z);
  a.vrm.update(dt);
}

function updateRobot(a, S, dt, t, g) {
  const k = Math.min(1, dt * 6);
  a.head.position.y = Math.sin(t * 1.7) * .02 + (S.state === 'speaking' ? Math.abs(Math.sin(t * 8)) * .015 * S.mouth : 0);
  const G = S.gesture, ge = G ? G.env : 0;
  let tL = -.12, tR = .12, gNod = 0, gYaw = 0, gBow = 0;
  if (G) {
    if (G.name === 'wave') tR = .12 + (2.5 + Math.sin(G.t * 11) * .3 - .12) * ge;
    else if (G.name === 'type') { tL = -.9 + Math.sin(G.t * 13) * .12; tR = .9 + Math.sin(G.t * 13 + 3) * .12; }
    else if (G.name === 'nod') gNod = Math.sin(G.t * 10) * .22 * ge;
    else if (G.name === 'shake') gYaw = Math.sin(G.t * 11) * .5 * ge;
    else if (G.name === 'bow') gBow = .35 * ge;
  }
  if (a.armL) { a.armL.rotation.z += (tL - a.armL.rotation.z) * k; a.armR.rotation.z += (tR - a.armR.rotation.z) * k; }
  a.root.rotation.x += (gBow - a.root.rotation.x) * k;
  const yaw = (cfg.track ? mouse.x * .4 : g[0] * .3) + gYaw, pitch = (cfg.track ? -mouse.y * .25 : -g[1] * .3) + cur.nod + gNod;
  a.head.rotation.y += (yaw - a.head.rotation.y) * k;
  a.head.rotation.x += (pitch - a.head.rotation.x) * k;
  a.head.rotation.z += (cur.tilt - a.head.rotation.z) * k;
  const open = Math.max(.08, cur.eye * (1 - Math.max(blinkVal, cur.blink)));
  a.eyes.forEach((w, i) => {
    w.scale.y = cur.squint > .5 ? .3 : 1.25 * open;
    a.pupils[i].visible = cur.squint <= .5 && open > .3;
    a.pupils[i].position.x = (i ? 1 : -1) * .19 + clamp(g[0], -1, 1) * .03;
    a.pupils[i].position.y = .08 + clamp(g[1], -1, 1) * .03;
    const s = i ? 1 : -1;
    a.brows[i].position.y = .27 - cur.brow * .04;
    a.brows[i].rotation.z = s * cur.inner * .45;
    a.cheeks[i].material.opacity = clamp(cur.blush, 0, 1) * .8;
  });
  const mo = Math.max(cur.open, S.mouth);
  if (mo > .08) {
    a.arc.visible = false; a.mouthO.visible = true;
    const vw = S.vis ? clamp(1 + .35 * ((S.vis[3] + S.vis[1]) - (S.vis[2] + S.vis[4])), .7, 1.35) : 1;
    a.mouthO.scale.set((1 + .4 * cur.happy) * vw, .15 + mo * 1.1, .4);
  } else {
    a.mouthO.visible = false; a.arc.visible = true;
    a.arc.scale.set(1, -cur.curve * .7, 1);
  }
  const c = STATE_COLOR[S.state] || '#8c96a3';
  a.ball.material.color.set(c); if (a.ball.material.emissive) a.ball.material.emissive.set(c);
}

function updateStatic(a, S, dt, t) { a.root.rotation.y = Math.sin(t * .6) * .25; }

function updateDom(S) {
  el('dot').style.background = STATE_COLOR[S.state] || '#8c96a3';
  const b = el('bubble');
  if (cfg.bubble && S.bubble) { b.textContent = S.bubble; b.style.display = 'block'; } else b.style.display = 'none';
}

let last = now();
function loop() {
  requestAnimationFrame(loop);
  const t = now(), dt = Math.min(.1, t - last); last = t;
  const S = brain.step(t);
  updateDom(S);
  if (!renderer || !avatar) return;
  for (const key in S.target) cur[key] += (S.target[key] - cur[key]) * Math.min(1, dt * 8);
  if (t >= nextBlink) { blinkT0 = t; nextBlink = t + 2.5 + Math.random() * 4; }
  blinkVal = 0;
  if (blinkT0 !== null) { const x = (t - blinkT0) / .16; if (x >= 1) blinkT0 = null; else blinkVal = 1 - Math.abs(2 * x - 1); }
  const g = gazeOffset(S, t);
  placeCamera();
  if (avatar.kind === 'vrm') updateVrm(avatar, S, dt, t, g);
  else if (avatar.kind === 'robot') updateRobot(avatar, S, dt, t, g);
  else updateStatic(avatar, S, dt, t);
  renderer.render(scene, camera);
}

function applyConfig(c) {
  const prevModel = cfg.model, prevColor = cfg.color;
  Object.assign(cfg, c || {});
  brain.sleepMin = Number(cfg.sleep) || 0;
  applyBg();
  if (!modelReady || cfg.model !== prevModel || (!cfg.model && cfg.color !== prevColor)) {
    modelReady = true; setModel(cfg.model);
  }
}

const es = new EventSource('/events');
es.onopen = () => el('dot').classList.remove('off');
es.onerror = () => el('dot').classList.add('off');
es.onmessage = ev => {
  let m = null;
  try { m = JSON.parse(ev.data); } catch (e) { return; }
  if (m && m.t === 'config') applyConfig(m.cfg); else brain.handle(m, now());
};
applyBg();
loop();
'''

