class Avatar3D:
    """3D-аватар: локальный веб-сервер (только 127.0.0.1) отдаёт страницу с three.js/VRM и поток событий (SSE)."""

    def __init__(self, app):
        self.app = app
        self.srv = None
        self.port = 8765
        self.clients = []
        self.lock = threading.Lock()
        self.cfg = {}

    @property
    def is_open(self):
        return self.srv is not None

    # ----- файлы и адреса -----
    @staticmethod
    def models():
        if not AVATAR3D_DIR.is_dir():
            return []
        return sorted(f.name for f in AVATAR3D_DIR.iterdir() if f.is_file() and f.suffix.lower() in (".vrm", ".glb"))

    def url(self, obs=False):
        return f"http://127.0.0.1:{self.port}/" + ("?bg=transparent" if obs else "")

    def page(self):
        im = DEFAULT_IMPORTMAP
        f = AVATAR3D_DIR / "importmap.json"
        if f.exists():
            try:
                d = json.loads(f.read_text(encoding="utf-8"))
                if isinstance(d, dict) and isinstance(d.get("imports"), dict):
                    im = d
            except Exception:
                pass
        return (HTML3D.replace("__IMPORTMAP__", json.dumps(im).replace("</", "<\\/"))
                .replace("__BRAIN__", BRAIN_JS).replace("__RENDER__", RENDER_JS))

    # ----- настройки (читаются в главном потоке, сервер берёт готовый словарь) -----
    def refresh_cfg(self):
        a = self.app
        col = a.avatar_color.get()
        hexcol = COLOR_PRESETS.get(col, col if str(col).startswith("#") else "#7aa2f7")
        model = a.avatar3d_model.get()
        self.cfg = {
            "model": "" if model == AVATAR3D_BUILTIN else model,
            "bg": AVATAR3D_BGS.get(a.avatar3d_bg.get(), "#1e1e1e"),
            "zoom": max(.3, min(3.0, a._num(a.avatar3d_zoom, 1.0, float))),
            "arm": max(0.0, min(1.6, a._num(a.avatar3d_arm, 1.1, float))),
            "track": bool(a.avatar3d_track.get()), "bubble": bool(a.avatar_bubble.get()),
            "sleep": a._num(a.avatar_sleep, 5), "color": hexcol}
        self.broadcast({"t": "config", "cfg": self.cfg})

    # ----- сервер -----
    def open(self, port):
        if self.srv is not None:
            return
        self.port = int(port)
        self.refresh_cfg()
        av = self

        class H(BaseHTTPRequestHandler):
            def log_message(self, *args):
                pass

            def _send(self, code, body=b"", ctype="text/plain; charset=utf-8"):
                self.send_response(code)
                self.send_header("Content-Type", ctype)
                self.send_header("Content-Length", str(len(body)))
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                if self.command != "HEAD":
                    self.wfile.write(body)

            do_HEAD = None

            def do_GET(self):
                path = unquote(urlparse(self.path).path)
                try:
                    if path == "/":
                        self._send(200, av.page().encode("utf-8"), "text/html; charset=utf-8")
                    elif path == "/config.json":
                        self._send(200, json.dumps(av.cfg).encode("utf-8"), "application/json")
                    elif path == "/models.json":
                        self._send(200, json.dumps(av.models()).encode("utf-8"), "application/json")
                    elif path == "/events":
                        av._sse(self)
                    elif path.startswith("/model/"):
                        av._file(self, AVATAR3D_DIR, path[7:], (".vrm", ".glb"))
                    elif path.startswith("/lib/"):
                        av._file(self, AVATAR3D_DIR / "lib", path[5:], (".js", ".mjs", ".json", ".wasm"))
                    else:
                        self._send(404, b"not found")
                except (BrokenPipeError, ConnectionError, OSError):
                    pass

        srv = ThreadingHTTPServer(("127.0.0.1", self.port), H)
        srv.daemon_threads = True
        self.srv = srv
        threading.Thread(target=srv.serve_forever, kwargs={"poll_interval": 0.3}, daemon=True).start()

    def close(self):
        srv, self.srv = self.srv, None
        if srv is None:
            return
        with self.lock:
            for q in self.clients:
                try:
                    q.put_nowait(None)
                except queue.Full:
                    pass
        try:
            srv.shutdown()
            srv.server_close()
        except Exception:
            pass

    shutdown = close

    def _file(self, h, base, rel, exts):
        try:
            base_r = base.resolve()
            path = (base / rel).resolve()
        except Exception:
            return h._send(404, b"not found")
        if base_r not in path.parents or not path.is_file() or path.suffix.lower() not in exts:
            return h._send(404, b"not found")
        size = path.stat().st_size
        h.send_response(200)
        h.send_header("Content-Type", MIME3D.get(path.suffix.lower(), "application/octet-stream"))
        h.send_header("Content-Length", str(size))
        h.send_header("Cache-Control", "no-cache")
        h.end_headers()
        with open(path, "rb") as f:
            while True:
                chunk = f.read(1 << 16)
                if not chunk:
                    break
                h.wfile.write(chunk)

    def _sse(self, h):
        q = queue.Queue(maxsize=400)
        with self.lock:
            self.clients.append(q)
        try:
            h.send_response(200)
            h.send_header("Content-Type", "text/event-stream")
            h.send_header("Cache-Control", "no-cache")
            h.end_headers()
            h.wfile.write(b"data: " + json.dumps({"t": "config", "cfg": self.cfg}).encode("utf-8") + b"\n\n")
            h.wfile.flush()
            while self.srv is not None:
                try:
                    item = q.get(timeout=15)
                except queue.Empty:
                    h.wfile.write(b": ping\n\n")
                    h.wfile.flush()
                    continue
                if item is None:
                    break
                h.wfile.write(b"data: " + item.encode("utf-8") + b"\n\n")
                h.wfile.flush()
        except (BrokenPipeError, ConnectionError, OSError):
            pass
        finally:
            with self.lock:
                if q in self.clients:
                    self.clients.remove(q)

    def broadcast(self, msg):
        if self.srv is None:
            return
        data = json.dumps(msg, ensure_ascii=False)
        with self.lock:
            for q in self.clients:
                try:
                    q.put_nowait(data)
                except queue.Full:
                    pass

    # ----- события приложения -> сообщения странице -----
    def handle(self, kind, kw):
        m = []
        if kind in ("listening", "thinking"):
            m.append({"t": "state", "state": kind})
        elif kind == "user_said":
            e = guess_emotion(kw.get("text", ""))
            if e:
                m.append({"t": "emotion", "name": e, "secs": 2.5})
        elif kind == "speak":
            env = kw.get("env")
            vis = kw.get("vis")
            m.append({"t": "speak", "env": np.asarray(env, dtype=float).round(2).tolist() if env is not None else None,
                      "vis": np.asarray(vis, dtype=float).round(2).tolist() if vis is not None else None,
                      "dur": float(kw.get("dur", 1.0)), "emotion": kw.get("emotion") or "neutral",
                      "text": kw.get("text", "")})
        elif kind == "emotion":
            m.append({"t": "emotion", "name": kw.get("name", "neutral"), "secs": 4})
        elif kind == "tool":
            name = kw.get("name", "")
            m += [{"t": "state", "state": "working"},
                  {"t": "bubble", "text": TOOL_BUBBLES.get(name, f"⚙ {name}"), "secs": 4}]
        elif kind == "error":
            m += [{"t": "state", "state": "idle"}, {"t": "emotion", "name": "sad", "secs": 4},
                  {"t": "bubble", "text": "Упс… " + str(kw.get("text", ""))[:70], "secs": 5}]
        elif kind == "alert":
            m += [{"t": "emotion", "name": "sad", "secs": 4},
                  {"t": "bubble", "text": str(kw.get("text", ""))[:80], "secs": 5}]
        elif kind == "interrupt":
            m += [{"t": "state", "state": "idle"}, {"t": "emotion", "name": "surprised", "secs": 1.0}]
        elif kind == "idle":
            m.append({"t": "state", "state": "idle"})
        elif kind == "say":
            m.append({"t": "bubble", "text": str(kw.get("text", "")), "secs": 4})
        elif kind == "sleep":
            m.append({"t": "state", "state": "sleeping"})
        elif kind == "gesture":
            g = kw.get("name", "nod")
            m.append({"t": "gesture", "name": g, "secs": GESTURE_SECS.get(g, 1.5)})
        for x in m:
            self.broadcast(x)


# ------------------------------- расширения: чистая логика -------------------------------
MEMORY_FILE = BASE / "memory.json"
REMINDERS_FILE = BASE / "reminders.json"
ACTIONS_LOG = BASE / "actions.log"
FILES_DIR_DEFAULT = BASE / "agent_files"
WAKE_ONLY_TEXT = "[Пользователь позвал тебя по имени. Откликнись одним-двумя словами, например «Слушаю».]"
UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) NightlordAgent/1.0"
TEXT_EXTS = {".txt", ".md", ".csv", ".tsv", ".json", ".log", ".py", ".js", ".html", ".xml", ".yml", ".yaml",
             ".ini", ".cfg", ".toml", ".bat", ".ps1", ".sql", ".rtf"}
REPEATS = {"": "Нет", "daily": "Каждый день", "weekdays": "По будням", "weekly": "Каждую неделю"}


def norm_ru(s):
    """Нижний регистр, ё→е, без знаков препинания (кроме : и -), одинарные пробелы."""
    s = (s or "").lower().replace("ё", "е")
    s = re.sub(r"[^\w\s:+-]", " ", s)
    return re.sub(r"\s+", " ", s).strip()


# ----- слово-активатор -----
def parse_wake_words(s):
    return [w for w in (norm_ru(x) for x in re.split(r"[,;\n]+", s or "")) if w]


def match_wake(text, words, thr=0.75):
    """Ищет обращение по имени. Возвращает (найдено, текст без имени)."""
    if not words:
        return True, text
    for ww in words:
        if " " in ww:  # фраза из нескольких слов — точное вхождение
            pat = r"\s*[,.!?-]*\s*".join(re.escape(x) for x in ww.split())
            m = re.search(pat, text.lower().replace("ё", "е"))
            if m:
                rest = re.sub(r"\s+", " ", (text[:m.start()] + " " + text[m.end():])).strip(" ,.!?;:-—")
                return True, rest
    for m in re.finditer(r"[\w'-]+", text):
        w = norm_ru(m.group(0))
        if len(w) < 3:
            continue
        for ww in words:
            if " " in ww or abs(len(w) - len(ww)) > 2:
                continue
            if w == ww or difflib.SequenceMatcher(None, w, ww).ratio() >= thr:
                rest = re.sub(r"\s+", " ", (text[:m.start()] + " " + text[m.end():])).strip(" ,.!?;:-—")
                return True, rest
    return False, text


# ----- числа словами и напоминания -----
_NUMW = {"ноль": 0, "один": 1, "одну": 1, "одна": 1, "два": 2, "две": 2, "три": 3, "четыре": 4, "пять": 5,
         "шесть": 6, "семь": 7, "восемь": 8, "девять": 9, "десять": 10, "одиннадцать": 11, "двенадцать": 12,
         "тринадцать": 13, "четырнадцать": 14, "пятнадцать": 15, "шестнадцать": 16, "семнадцать": 17,
         "восемнадцать": 18, "девятнадцать": 19, "двадцать": 20, "тридцать": 30, "сорок": 40,
         "пятьдесят": 50, "шестьдесят": 60}


def numwords_to_digits(text):
    toks, out, i = text.split(), [], 0
    while i < len(toks):
        v = _NUMW.get(toks[i])
        if v is None:
            out.append(toks[i])
            i += 1
            continue
        if v >= 20 and i + 1 < len(toks) and 0 < _NUMW.get(toks[i + 1], 99) < 10:
            v += _NUMW[toks[i + 1]]
            i += 1
        out.append(str(v))
        i += 1
    return " ".join(out)


_UNIT = [(r"секунд\w*|сек", 1 / 60), (r"минут\w*|мин", 1), (r"час\w*|ч", 60), (r"дн\w*|день|дня|дней", 1440)]


def parse_reminder(text, now=None):
    """Разбирает «через 20 минут выключить плиту», «в 18:30 позвонить», «каждый день в 9 зарядка».
    Возвращает {"when": datetime, "text": str, "repeat": str} или None."""
    now = now or datetime.now()
    t = numwords_to_digits(norm_ru(text))
    repeat = ""
    when = None
    m = re.search(r"\bкаждые (\d+) (минут\w*|мин|час\w*)", t)
    if m:
        n = int(m.group(1)) * (60 if m.group(2).startswith("час") else 1)
        repeat, when = f"every:{max(1, n)}", now + timedelta(minutes=max(1, n))
        t = (t[:m.start()] + " " + t[m.end():])
    elif re.search(r"\b(каждый день|ежедневно|каждое утро|каждый вечер)\b", t):
        repeat = "daily"
    elif re.search(r"\b(по будням|в будни|каждый будний день)\b", t):
        repeat = "weekdays"
    elif re.search(r"\b(каждую неделю|раз в неделю|еженедельно)\b", t):
        repeat = "weekly"
    t = re.sub(r"\b(каждый день|ежедневно|каждое утро|каждый вечер|по будням|в будни|каждый будний день|"
               r"каждую неделю|раз в неделю|еженедельно)\b", " ", t)
    if when is None:
        if re.search(r"\bчерез полчаса\b", t):
            when = now + timedelta(minutes=30)
            t = re.sub(r"\bчерез полчаса\b", " ", t, count=1)
        else:
            m = re.search(r"\bчерез (?:(\d+) )?(секунд\w*|сек|минут\w*|мин|час\w*|ч|день|дня|дней)\b", t)
            if m:
                n = int(m.group(1)) if m.group(1) else 1
                for rx, mult in _UNIT:
                    if re.fullmatch(rx, m.group(2)):
                        when = now + timedelta(minutes=n * mult)
                        break
                t = t[:m.start()] + " " + t[m.end():]
    if when is None:
        day = 0
        if re.search(r"\bзавтра\b", t):
            day = 1
            t = re.sub(r"\bзавтра\b", " ", t, count=1)
        elif re.search(r"\bпослезавтра\b", t):
            day = 2
            t = re.sub(r"\bпослезавтра\b", " ", t, count=1)
        m = re.search(r"\b(?:в|к) (\d{1,2})(?:[: .](\d{2}))?(?: (час\w*|утра|вечера|дня|ночи))?(?= |$)", t)
        if m and (m.group(2) is not None or m.group(3) or repeat or day):
            h, mi = int(m.group(1)), int(m.group(2) or 0)
            part = m.group(3) or ""
            if part in ("вечера", "дня") and h < 12:
                h += 12
            elif part == "ночи" and h == 12:
                h = 0
            if h < 24 and mi < 60:
                when = now.replace(hour=h, minute=mi, second=0, microsecond=0) + timedelta(days=day)
                if when <= now:
                    when += timedelta(days=1)
                t = t[:m.start()] + " " + t[m.end():]
        elif repeat == "daily" and re.search(r"\bутро\b", text.lower()):
            when = now.replace(hour=9, minute=0, second=0, microsecond=0)
            if when <= now:
                when += timedelta(days=1)
    if when is None:
        return None
    task = re.sub(r"\s+", " ", t).strip()
    task = re.sub(r"^(мне |пожалуйста |что |чтобы |о том что |о том чтобы |о |об |про |что надо |что нужно )+", "",
                  task).strip(" ,.-")
    if repeat == "weekdays" and when.weekday() >= 5:
        when += timedelta(days=7 - when.weekday())
    return {"when": when, "text": task or "напоминание", "repeat": repeat}


def next_reminder_time(when, repeat, now=None):
    """Следующее срабатывание повторяющегося напоминания (строго после now) или None."""
    now = now or datetime.now()
    if not repeat:
        return None
    if repeat.startswith("every:"):
        step = timedelta(minutes=max(1, int(repeat.split(":")[1])))
        while when <= now:
            when += step
        return when
    step = {"daily": timedelta(days=1), "weekdays": timedelta(days=1), "weekly": timedelta(days=7)}.get(repeat)
    if step is None:
        return None
    while when <= now or (repeat == "weekdays" and when.weekday() >= 5):
        when += step
    return when


def repeat_label(repeat):
    if repeat.startswith("every:"):
        return f"Каждые {repeat.split(':')[1]} мин"
    return REPEATS.get(repeat, repeat or "Нет")


# ----- долгая память -----
MEM_LOCK = threading.Lock()


def mem_load():
    with MEM_LOCK:
        d = load_json(MEMORY_FILE, [])
    return [x for x in d if isinstance(x, dict) and x.get("t")] if isinstance(d, list) else []


def _mem_save(items):
    save_json(MEMORY_FILE, items)


def mem_add(text):
    text = re.sub(r"\s+", " ", str(text or "")).strip(" .,;")
    if not text:
        return False
    with MEM_LOCK:
        d = load_json(MEMORY_FILE, [])
        d = d if isinstance(d, list) else []
        if any(norm_ru(x.get("t", "")) == norm_ru(text) for x in d if isinstance(x, dict)):
            return False
        d.append({"t": text[:300], "ts": datetime.now().strftime("%Y-%m-%d %H:%M")})
        _mem_save(d[-300:])
    return True


def mem_forget(query):
    """Удаляет записи, содержащие запрос (все его слова). Возвращает число удалённых."""
    words = [w for w in norm_ru(query).split() if len(w) > 2 and w not in ("про", "что", "это", "все", "мне", "обо", "как")]
    stems = [w[:max(3, len(w) - 2)] for w in words]
    if not stems:
        return 0
    with MEM_LOCK:
        d = load_json(MEMORY_FILE, [])
        d = d if isinstance(d, list) else []
        keep = [x for x in d if not (isinstance(x, dict) and all(s in norm_ru(x.get("t", "")) for s in stems))]
        n = len(d) - len(keep)
        if n:
            _mem_save(keep)
    return n


def mem_prompt(max_chars=1200):
    items = [x["t"] for x in mem_load()]
    out, total = [], 0
    for t in reversed(items):  # свежие важнее
        if total + len(t) + 3 > max_chars:
            break
        out.append("- " + t)
        total += len(t) + 3
    return "\n".join(reversed(out))


# ----- файлы -----
def safe_path(base, rel):
    """Путь внутри base. Абсолютные пути, .. и символические ссылки наружу — ошибка."""
    base_r = Path(base).resolve()
    rel = str(rel or ".").strip().strip('"').replace("\\", "/")
    p = Path(rel)
    if p.is_absolute():
        try:
            p = p.resolve().relative_to(base_r)
        except ValueError:
            raise ValueError("путь вне разрешённой папки")
    full = (base_r / p).resolve()
    if full != base_r and base_r not in full.parents:
        raise ValueError("путь вне разрешённой папки")
    return full


def read_any(path, limit=6000):
    """Текст из txt/md/csv/json/…, а также docx и (если установлен pypdf) pdf."""
    path = Path(path)
    ext = path.suffix.lower()
    if ext == ".docx":
        import zipfile
        with zipfile.ZipFile(path) as z:
            xml = z.read("word/document.xml").decode("utf-8", "ignore")
        xml = re.sub(r"</w:p>", "\n", xml)
        text = html_lib.unescape(re.sub(r"<[^>]+>", "", xml))
    elif ext == ".pdf":
        try:
            from pypdf import PdfReader
        except ImportError:
            raise ValueError("для PDF нужен пакет pypdf: вкладка «Компоненты» или py -3.12 -m pip install pypdf")
        text = "\n".join((pg.extract_text() or "") for pg in PdfReader(str(path)).pages[:30])
    elif ext in TEXT_EXTS:
        raw = path.read_bytes()[:2_000_000]
        for enc in ("utf-8-sig", "cp1251"):
            try:
                text = raw.decode(enc)
                break
            except UnicodeDecodeError:
                continue
        else:
            text = raw.decode("utf-8", "replace")
    else:
        raise ValueError(f"тип файла {ext or '(без расширения)'} не поддерживается")
    text = text.strip()
    if len(text) > limit:
        text = text[:limit] + f"\n…[обрезано, всего {len(text)} символов]"
    return text or "(файл пуст)"


# ----- веб -----
def _strip_tags(s):
    return re.sub(r"\s+", " ", html_lib.unescape(re.sub(r"<[^>]+>", " ", s or ""))).strip()


def _ddg_real_url(href):
    href = html_lib.unescape(href or "")
    if href.startswith("//"):
        href = "https:" + href
    q = parse_qs(urlparse(href).query)
    return unquote(q["uddg"][0]) if q.get("uddg") else href


def parse_ddg(html, n=5):
    """Разбор html.duckduckgo.com/html и lite.duckduckgo.com/lite. Возвращает [(заголовок, ссылка, описание)]."""
    out = []
    parts = re.split(r'(?=<a[^>]+class=["\'][^"\']*result__a)', html)
    for seg in parts[1:]:
        tag = re.match(r"<a[^>]*>", seg)
        href = re.search(r'href="([^"]+)"', tag.group(0)) if tag else None
        title = re.search(r"<a[^>]*>(.*?)</a>", seg, re.S)
        snip = re.search(r'class="result__snippet"[^>]*>(.*?)</(?:a|td|div)>', seg, re.S)
        if href and title:
            out.append((_strip_tags(title.group(1)), _ddg_real_url(href.group(1)),
                        _strip_tags(snip.group(1)) if snip else ""))
    if not out:  # lite-версия
        for m in re.finditer(r"<a[^>]+class=['\"]result-link['\"][^>]*>.*?</a>", html, re.S):
            tag = m.group(0)
            href = re.search(r"href=['\"]([^'\"]+)['\"]", tag)
            rest = html[m.end():m.end() + 1500]
            sn = re.search(r"class=['\"]result-snippet['\"][^>]*>(.*?)</td>", rest, re.S)
            if href:
                out.append((_strip_tags(tag), _ddg_real_url(href.group(1)), _strip_tags(sn.group(1)) if sn else ""))
    seen, res = set(), []
    for t, u, s in out:
        if u and u not in seen and "duckduckgo.com/y.js" not in u:
            seen.add(u)
            res.append((t, u, s))
    return res[:n]


NET_PROXY = {"web": None, "tg": None, "ip": None, "models": None}   # задаёт плагин «VPN / прокси»


def _px(kind):
    return NET_PROXY.get(kind)


def explain_proxy_error(e):
    s = str(e)
    if "Missing dependencies for SOCKS" in s or "SOCKS support" in s:
        return "для SOCKS нужен пакет PySocks: вкладка «Компоненты» или py -3.12 -m pip install pysocks"
    low = s.lower()
    if any(k in low for k in ("refused", "10061", "proxyerror", "unable to connect to proxy", "failed to establish")):
        return "прокси не отвечает: запущен ли клиент (v2rayN, Hiddify…) и верны ли адрес и порт?"
    if "407" in s or "authentication" in low or "auth" in low and "proxy" in low:
        return "прокси отклонил логин или пароль"
    if "timed out" in low or "timeout" in low:
        return "прокси не ответил вовремя"
    return s[:160]


def web_search(query, n=5, timeout=10):
    q = str(query or "").strip()
    if not q:
        return "Пустой поисковый запрос"
    last = None
    for url, method in (("https://html.duckduckgo.com/html/", "post"), ("https://lite.duckduckgo.com/lite/", "post")):
        try:
            r = requests.post(url, data={"q": q, "kl": "ru-ru"}, headers={"User-Agent": UA}, timeout=timeout,
                              proxies=_px("web"))
            r.raise_for_status()
            res = parse_ddg(r.text, n)
            if res:
                return "\n".join(f"{i}. {t} — {s[:240]} ({u})" for i, (t, u, s) in enumerate(res, 1))
        except Exception as e:
            last = e
    return "Ничего не найдено" if last is None else f"Поиск недоступен: {last}"


def _host_is_public(host):
    try:
        infos = socket.getaddrinfo(host, None)
    except OSError:
        return False
    for info in infos:
        ip = ipaddress.ip_address(info[4][0].split("%")[0])
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved or ip.is_multicast:
            return False
    return True


class _TextExtractor(HTMLParser):
    SKIP = {"script", "style", "noscript", "svg", "head", "nav", "footer", "form"}

    def __init__(self):
        super().__init__()
        self.skip, self.out = 0, []

    def handle_starttag(self, tag, attrs):
        if tag in self.SKIP:
            self.skip += 1
        elif tag in ("p", "br", "div", "li", "h1", "h2", "h3", "tr"):
            self.out.append("\n")

    def handle_endtag(self, tag):
        if tag in self.SKIP and self.skip:
            self.skip -= 1

    def handle_data(self, data):
        if not self.skip:
            self.out.append(data)


def read_webpage(url, limit=3500, timeout=10):
    """Текст страницы. Только http/https и только публичные адреса (не localhost и не локальная сеть)."""
    for _ in range(4):
        u = urlparse(url)
        if u.scheme not in ("http", "https") or not u.hostname:
            raise ValueError("разрешены только ссылки http/https")
        if not _host_is_public(u.hostname):
            raise ValueError("адрес не публичный (localhost и локальная сеть запрещены)")
        r = requests.get(url, headers={"User-Agent": UA}, timeout=timeout, stream=True, allow_redirects=False,
                         proxies=_px("web"))
        if r.is_redirect or r.status_code in (301, 302, 303, 307, 308):
            url = requests.compat.urljoin(url, r.headers.get("Location", ""))
            r.close()
            continue
        r.raise_for_status()
        ctype = r.headers.get("Content-Type", "")
        if "html" not in ctype and "text" not in ctype:
            raise ValueError(f"не текстовая страница ({ctype or 'тип неизвестен'})")
        raw = r.raw.read(1_500_000, decode_content=True)
        r.close()
        enc = r.encoding or "utf-8"
        try:
            body = raw.decode(enc, "replace")
        except LookupError:
            body = raw.decode("utf-8", "replace")
        ex = _TextExtractor()
        ex.feed(body)
        text = re.sub(r"[ \t]+", " ", html_lib.unescape("".join(ex.out)))
        text = re.sub(r"\n\s*\n+", "\n", text).strip()
        return text[:limit] + (" …[обрезано]" if len(text) > limit else "") if text else "(на странице нет текста)"
    raise ValueError("слишком много перенаправлений")


# ----- голосовые команды (разбираются до обращения к модели) -----
def _hot_match(t, pattern):
    return re.match(pattern, t)


def match_hot(text):
    """Возвращает (команда, аргумент) или None. Работает по нормализованному тексту."""
    t = norm_ru(text)
    n = len(t.split())
    if not t:
        return None
    # команды с содержимым
    m = re.match(r"^(?:пожалуйста )?запомни(?: что| то что)? (.{3,})$", t)
    if m:
        return "remember", text_after(
            text, m.group(1), r"^\W*(?:пожалуйста\W+)?запомни(?:\W+(?:то\W+что|что))?\W+")
    m = re.match(r"^(?:пожалуйста )?забудь (?!диалог|разговор|все что)(.{3,})$", t)
    if m:
        return "forget", m.group(1)
    m = re.match(r"^(?:пожалуйста )?напомни(?: мне)? (.{3,})$", t)
    if m:
        return "remind", m.group(1)
    m = re.match(r"^(?:пожалуйста )?(?:найди|поищи|посмотри) (?:в интернете|в сети|в гугле|в поиске|в инете)"
                 r"(?: что такое| информацию о| информацию про| про| о)? ?(.{2,})$", t)
    if m:
        return "search", m.group(1).strip()
    m = re.match(r"^(?:загугли|погугли) (.{2,})$", t)
    if m:
        return "search", m.group(1).strip()
    m = re.match(r"^(?:включи |переключись на |перейди в |давай |активируй )?режим (.{2,})$", t)
    if m and n <= 8:
        return "mode", m.group(1).strip()
    m = re.match(r"^громкость (?:на )?(\d{1,3})(?: процент\w*)?$", t)
    if m:
        return "volume", int(m.group(1))
    m = re.match(r"^(?:смени|поменяй|измени) голос на (.{2,})$", t) or re.match(r"^голос (.{2,})$", t)
    if m and n <= 6:
        return "voice", m.group(1).strip()
    if n > 7:
        return None
    pats = [
        (r"^(?:ну )?(?:стоп|хватит|замолчи|помолчи|тихо|перестань|остановись)$", "stop", None),
        (r"^(?:очисти|сотри) (?:диалог|чат|историю)$|^новый диалог$|^начни заново$|^забудь (?:диалог|разговор)$",
         "clear", None),
        (r"^(?:сделай )?(?:погромче|громче)$|^прибавь (?:громкость|звук)$|^увеличь громкость$", "louder", None),
        (r"^(?:сделай )?(?:потише|тише)$|^убавь (?:громкость|звук)$|^уменьши громкость$", "quieter", None),
        (r"^(?:смени|поменяй|измени) голос$|^другой голос$", "voice_next", None),
        (r"^(?:выключи|отключи) озвучку$|^не озвучивай$", "tts_off", None),
        (r"^включи озвучку$", "tts_on", None),
        (r"^(?:не слушай|выключи микрофон|отключи микрофон)$", "mic_off", None),
        (r"^(?:включи|покажи|верни) аватар\w*$", "avatar_on", None),
        (r"^(?:выключи|убери|спрячь|скрой) аватар\w*$", "avatar_off", None),
        (r"^(?:какие|список) режим\w*$|^какие есть режимы$", "modes_list", None),
        (r"^что ты (?:помнишь|знаешь обо мне|запомнил\w*)$|^(?:покажи|прочитай) память$", "memory_list", None),
        (r"^(?:очисти|сотри) (?:всю )?память$|^забудь все что я говорил$", "memory_clear", None),
        (r"^(?:какие|список|что за) напоминани\w*$|^мои напоминания$", "remind_list", None),
        (r"^(?:отмени|удали|сотри) (?:все )?напоминани\w*$", "remind_clear", None),
        (r"^который час$|^сколько (?:сейчас )?времени$|^какое (?:сейчас )?время$|^скажи время$", "time", None),
        (r"^какое (?:сегодня )?число$|^какая (?:сегодня )?дата$|^какой (?:сегодня )?день$|^какое сегодня число$",
         "date", None),
        (r"^отмени (?:последнее|предыдущее) действие$|^отмени действие$", "undo", None),
        (r"^проверь (?:все|систему|связь|подключени\w*)$", "selftest", None),
    ]
    for rx, kind, _ in pats:
        if re.match(rx, t):
            return kind, None
    return None


def text_after(original, normalized_tail, cmd_rx=None):
    """Хвост команды из исходного текста (с регистром); если не получилось — нормализованный."""
    if cmd_rx:
        m = re.match(cmd_rx, original or "", re.I)
        if m and original[m.end():].strip(" .!"):
            return original[m.end():].strip(" .!")
    return normalized_tail


def find_profile(query, names):
    """Подбор профиля/промта по сказанному названию («переводчика» → «Переводчик»)."""
    q = norm_ru(query)
    toks = [x for x in q.split() if len(x) >= 3]
    best, score = None, 0.0
    for name in names:
        nn = norm_ru(name)
        s = 0.0
        if q and (q == nn or q in nn):
            s += 5
        for tk_ in toks:
            stem = tk_[:max(4, len(tk_) - 2)]
            if stem in nn:
                s += 2
            else:
                s += max(difflib.SequenceMatcher(None, tk_, w).ratio() for w in nn.split() or [""]) - .5
        if s > score:
            best, score = name, s
    return best if score >= 1.0 else None


# ----- жесты аватара -----
_GEST_RE = [
    ("wave", re.compile(r"(?<!\w)(привет|здравствуй|здорово|хай|пока|до свидания|до встречи|hello|hi|bye)(?!\w)", re.I)),
    ("bow", re.compile(r"(?<!\w)(спасибо|благодарю|извини\w*|прости\w*|thanks|sorry)(?!\w)", re.I)),
    ("shake", re.compile(r"(?<!\w)(нет|не могу|невозможно|к сожалению|не знаю|не получится|no)(?!\w)", re.I)),
    ("nod", re.compile(r"(?<!\w)(да|конечно|хорошо|ладно|понял\w*|договорились|согласен|окей|ок|yes|sure)(?!\w)", re.I)),
]


def guess_gesture(text):
    t = (text or "")[:160]
    for name, rx in _GEST_RE:
        if rx.search(t):
            return name
    return None


