class ExtrasMixin:
    """Дополнительные возможности: имя-активатор, голосовые команды, память, напоминания, файлы и веб,
    события ПК, трей, журнал действий и самопроверка. Методы вызываются из класса App."""

    # ---------- переменные и запуск ----------
    def _init_extra_vars(self):
        B, S, I = tk.BooleanVar, tk.StringVar, tk.IntVar
        self.wake_on = B(value=False)
        self.out_dev = S(value="По умолчанию (система)")   # устройство вывода звука
        self.output_devices = {"По умолчанию (система)": None}
        self._out_idx = None
        self.wake_words = S(value="Ника, Nika")
        self.wake_window = I(value=20)
        self.hot_on = B(value=True)
        self.web_on = B(value=True)
        self.volume = I(value=100)
        self.mem_on = B(value=True)
        self.rem_on = B(value=True)
        self.files_dir = S(value=str(FILES_DIR_DEFAULT))
        self.files_write = B(value=False)
        self.ev_on = B(value=False)
        self.ev_proc = S(value="")
        self.ev_cpu = B(value=True)
        self.ev_battery = B(value=True)
        self.ev_downloads = B(value=True)
        self.ev_break = B(value=False)
        self.ev_break_min = I(value=60)
        self.ev_llm = B(value=False)
        self.tray_on = B(value=False)
        self.act_log_on = B(value=True)
        self.avatar_gest = B(value=True)
        self._wake_until = 0.0
        self._volume = 1.0
        self._act_on = True
        self._gest_on = True
        self.avatar_gest.trace_add("write", lambda *a: setattr(self, "_gest_on", bool(self.avatar_gest.get())))
        self.reminders = []
        self._rem_lock = threading.Lock()
        self.action_log = []
        self._act_lock = threading.Lock()
        self._tray = None
        self._ev = {"procs": None, "hot": 0, "bat_warned": False, "dl": None, "dl_pending": {},
                    "cool": {}, "last_break": time.time()}
        self.volume.trace_add("write", self._sync_volume)
        self.act_log_on.trace_add("write", lambda *a: setattr(self, "_act_on", bool(self.act_log_on.get())))

    def _sync_volume(self, *a):
        try:
            self._volume = max(0.0, min(2.0, int(self.volume.get()) / 100))
        except (tk.TclError, ValueError):
            pass

    def _extra_setting_vars(self):
        return {k: getattr(self, k) for k in (
            "wake_on", "wake_words", "wake_window", "out_dev", "hot_on", "web_on", "volume", "mem_on", "rem_on", "files_dir",
            "files_write", "ev_on", "ev_proc", "ev_cpu", "ev_battery", "ev_downloads", "ev_break", "ev_break_min",
            "ev_llm", "tray_on", "act_log_on", "avatar_gest")}

    def _extras_start(self):
        self._sync_volume()
        self._act_on = bool(self.act_log_on.get())
        self._rem_load()
        self.root.after(3000, self._rem_tick)
        self.root.after(6000, self._events_tick)
        self.root.bind("<Unmap>", self._on_unmap, add="+")
        if self.tray_on.get():
            self.root.after(800, self._tray_apply)

    # ---------- общая озвучка без обращения к модели ----------
    def say_direct(self, text, emotion=None):
        """Озвучить готовую фразу (из любого потока). Ждёт, пока агент не занят."""
        threading.Thread(target=self._say_direct_worker, args=(text, emotion), daemon=True).start()

    def _say_direct_worker(self, text, emotion):
        for _ in range(240):
            if not self.busy:
                break
            time.sleep(0.5)
        else:
            self.append("Агент", text, "bot")
            return
        try:
            cfg = self.call_ui(self._make_cfg)
        except Exception:
            return

        def begin():
            self.busy = True
            self.gen += 1
            self.speaking = False
            return self.gen
        gen = self.call_ui(begin)
        emo = emotion or guess_emotion(text) or "neutral"
        self.append("Агент", text, "bot")
        q = queue.Queue()
        player = self._start_speaker(cfg, gen, q, time.perf_counter()) if cfg["speak"] else None
        if player:
            q.put((text, emo))
        else:
            self.avatar_event("speak", env=None, dur=min(6.0, .06 * len(text) + 1.0), emotion=emo, text=text)
        q.put(None)
        if player:
            player.join()
        if gen == self.gen:
            self.busy = False
            self.set_status("Готов")
            self.avatar_event("idle")

    # ---------- имя-активатор ----------
    def wake_filter(self, cfg, text):
        """(текст для обработки или None, если фраза не по имени)."""
        words = cfg["wake_words_list"]
        found, rest = match_wake(text, words)
        if found:
            return rest or WAKE_ONLY_TEXT
        if time.time() < self._wake_until:
            return text
        return None

    # ---------- голосовые команды ----------
    def hot_dispatch(self, cfg, text):
        r2 = self.hot2_dispatch(cfg, text)
        if r2 is not None:
            return r2
        m = match_hot(text)
        if not m:
            return self.plugin_dispatch(cfg, text)
        kind, arg = m
        if kind == "search" and not cfg["web_on"]:
            return None
        try:
            return self._hot_run(cfg, kind, arg, text)
        except Exception as e:
            return ("say", f"Не получилось выполнить команду: {e}")

    def _hot_run(self, cfg, kind, arg, text):
        U = self.call_ui
        say = lambda s: ("say", s)
        if kind == "stop":
            U(self.interrupt)
            return ("silent", None)
        if kind == "clear":
            U(self.clear_chat)
            return say("Диалог очищен.")
        if kind in ("louder", "quieter", "volume"):
            def f():
                cur = int(self.volume.get())
                v = cur + 20 if kind == "louder" else cur - 20 if kind == "quieter" else int(arg)
                v = max(0, min(200, v))
                self.volume.set(v)
                return v
            return say(f"Громкость {U(f)} процентов.")
        if kind in ("voice_next", "voice"):
            vals = U(lambda: list(self.profile_combo["values"]))
            if not vals:
                return say("Список голосов пуст. Нажмите обновить рядом с голосом.")
            if kind == "voice_next":
                cur = U(self.vb_profile.get)
                name = vals[(vals.index(cur) + 1) % len(vals)] if cur in vals else vals[0]
            else:
                name = find_profile(arg, vals)
                if not name:
                    return None
            U(lambda: self.vb_profile.set(name))
            return say(f"Голос: {name}.")
        if kind == "mode":
            names = list(self.profiles) if U(self.profiles_on.get) else []
            best = find_profile(arg, names)
            if best:
                def f():
                    self.profile_name.set(best)
                    self.apply_profile()
                U(f)
                return say(f"Режим «{best}».")
            pm = find_profile(arg, list(self.prompts))
            if pm:
                def f():
                    self.prompt_name.set(pm)
                    self.on_prompt_change()
                U(f)
                return say(f"Промт «{pm}».")
            return None
        if kind == "modes_list":
            names = list(self.profiles)
            return say("Доступные режимы: " + ", ".join(names) + "." if names else "Профилей пока нет.")
        if kind in ("tts_off", "tts_on"):
            U(lambda: self.speak_on.set(kind == "tts_on"))
            return say("Озвучка включена." if kind == "tts_on" else "Озвучка выключена.")
        if kind == "mic_off":
            U(self.stop_input)
            return say("Микрофон выключен.")
        if kind in ("avatar_on", "avatar_off"):
            def f():
                self.avatar_on.set(kind == "avatar_on")
                self._on_avatar_toggle()
            U(f)
            return say("Аватар включён." if kind == "avatar_on" else "Аватар скрыт.")
        if kind in ("remember", "forget", "memory_list", "memory_clear"):
            if not cfg["mem_on"]:
                return say("Долгая память выключена в настройках.")
            if kind == "remember":
                return say("Хорошо, запомню." if mem_add(arg) else "Это я уже знаю.")
            if kind == "forget":
                n = mem_forget(arg)
                return say(f"Удалено записей: {n}." if n else "Ничего подходящего не нашлось.")
            if kind == "memory_list":
                items = [x["t"] for x in mem_load()]
                if not items:
                    return say("Пока ничего не запомнено.")
                return say("Я помню: " + "; ".join(items[-8:]) + ".")
            ok = U(lambda: messagebox.askyesno("Память", "Удалить всю долгую память?"), timeout=60)
            if ok:
                with MEM_LOCK:
                    _mem_save([])
                return say("Память очищена.")
            return say("Оставляю как есть.")
        if kind in ("remind", "remind_list", "remind_clear"):
            if not cfg["rem_on"]:
                return say("Напоминания выключены в настройках.")
            if kind == "remind":
                r = parse_reminder(arg)
                if not r:
                    return say("Не удалось разобрать время. Скажите, например: напомни через 20 минут выключить плиту.")
                self.add_reminder(r["when"], r["text"], r["repeat"])
                return say(f"Напомню {self._when_phrase(r['when'])}: {r['text']}."
                           + (f" Повтор: {repeat_label(r['repeat']).lower()}." if r["repeat"] else ""))
            if kind == "remind_list":
                with self._rem_lock:
                    rs = list(self.reminders[:5])
                if not rs:
                    return say("Напоминаний нет.")
                return say("Ближайшие напоминания: " + "; ".join(
                    f"{self._when_phrase(datetime.fromisoformat(r['when']))} — {r['text']}" for r in rs) + ".")
            n = self.cancel_reminders()
            return say(f"Удалено напоминаний: {n}." if n else "Напоминаний нет.")
        if kind == "search":
            self.avatar_event("tool", name="web_search")
            self.set_status(f"Ищу в интернете: {arg}…")
            res = web_search(arg, 5)
            self.append("🔎 поиск", f"{arg} → {res[:300]}", "tool")
            return ("llm", f"Вопрос пользователя: {arg}\n\nРезультаты поиска в интернете:\n{res}\n\n"
                           f"Ответь на вопрос кратко и своими словами по этим результатам. Адреса сайтов вслух не читай.")
        if kind == "time":
            return say(f"Сейчас {datetime.now():%H:%M}.")
        if kind == "date":
            d = datetime.now()
            return say(f"Сегодня {RU_DAYS[d.weekday()]}, {d.day} {RU_MONTHS[d.month - 1]} {d.year} года.")
        if kind == "undo":
            return say(self.undo_last())
        if kind == "selftest":
            U(self.run_selftest)
            return say("Запускаю проверку системы.")
        return None

    @staticmethod
    def _when_phrase(when):
        now = datetime.now()
        delta = (when - now).total_seconds()
        if delta < 0:
            return "сейчас"
        if delta < 3 * 3600:
            m = max(1, round(delta / 60))
            return f"через {m} мин" if m < 120 else f"через {m // 60} ч {m % 60} мин"
        day = ""
        if when.date() == (now + timedelta(days=1)).date():
            day = "завтра "
        elif when.date() != now.date():
            day = f"{when.day} {RU_MONTHS[when.month - 1]} "
        return f"{day}в {when:%H:%M}"

    # ---------- напоминания ----------
    def _rem_load(self):
        d = load_json(REMINDERS_FILE, [])
        out = []
        for r in d if isinstance(d, list) else []:
            try:
                datetime.fromisoformat(r["when"])
                out.append({"id": int(r["id"]), "when": r["when"], "text": str(r["text"]),
                            "repeat": str(r.get("repeat", "")), "ask": bool(r.get("ask"))})
            except (KeyError, ValueError, TypeError):
                continue
        with self._rem_lock:
            self.reminders = sorted(out, key=lambda r: r["when"])

    def _rem_save(self):
        save_json(REMINDERS_FILE, self.reminders)

    def add_reminder(self, when, text, repeat="", ask=False):
        with self._rem_lock:
            rid = max([r["id"] for r in self.reminders] + [0]) + 1
            self.reminders.append({"id": rid, "when": when.strftime("%Y-%m-%dT%H:%M:%S"), "text": str(text)[:300],
                                   "repeat": repeat, "ask": bool(ask)})
            self.reminders.sort(key=lambda r: r["when"])
            self._rem_save()
        self.ui(self._rem_refresh)
        return rid

    def cancel_reminders(self, rid=None):
        with self._rem_lock:
            before = len(self.reminders)
            self.reminders = [r for r in self.reminders if rid is not None and r["id"] != rid]
            n = before - len(self.reminders)
            if n:
                self._rem_save()
        self.ui(self._rem_refresh)
        return n

    def _rem_refresh(self):
        tree = getattr(self, "rem_tree", None)
        if tree is None:
            return
        tree.delete(*tree.get_children())
        with self._rem_lock:
            rs = list(self.reminders)
        for r in rs:
            w = datetime.fromisoformat(r["when"])
            tree.insert("", "end", iid=str(r["id"]), values=(
                w.strftime("%d.%m %H:%M"), r["text"] + (" (вопрос модели)" if r["ask"] else ""),
                repeat_label(r["repeat"])))

    def _rem_tick(self):
        try:
            if self.rem_on.get():
                now = datetime.now()
                with self._rem_lock:
                    due = [r for r in self.reminders if datetime.fromisoformat(r["when"]) <= now]
                for r in due:
                    if r["ask"] and self.busy:
                        continue  # подождём, пока агент освободится
                    self._rem_fire(r, now)
        except Exception as e:
            self.status.set(f"Напоминания: {e}")
        finally:
            self.root.after(5000, self._rem_tick)

    def _rem_fire(self, r, now):
        when = datetime.fromisoformat(r["when"])
        late = (now - when).total_seconds() > 2 * 3600
        with self._rem_lock:
            nxt = next_reminder_time(when, r["repeat"], now)
            if nxt:
                r["when"] = nxt.strftime("%Y-%m-%dT%H:%M:%S")
            else:
                self.reminders = [x for x in self.reminders if x["id"] != r["id"]]
            self.reminders.sort(key=lambda x: x["when"])
            self._rem_save()
        self._rem_refresh()
        self.avatar_event("say", text="🔔 " + r["text"][:60])
        self.avatar_event("gesture", name="wave")
        self._plug_emit("reminder", "🔔 " + r["text"])
        if r["ask"]:
            self.start_pipeline(text=r["text"])
        else:
            self.say_direct(("Пропущенное напоминание: " if late else "Напоминание: ") + r["text"])

    def _rem_dialog(self):
        win = tk.Toplevel(self.root)
        win.title("Новое напоминание")
        win.transient(self.root)
        win.resizable(False, False)
        text, mins, at = tk.StringVar(), tk.StringVar(value="10"), tk.StringVar()
        rep, ask = tk.StringVar(value=REPEATS[""]), tk.BooleanVar(value=False)
        f = ttk.Frame(win, padding=12)
        f.pack()
        ttk.Label(f, text="Текст").grid(row=0, column=0, sticky="w", pady=3)
        ent = ttk.Entry(f, textvariable=text, width=40)
        ent.grid(row=0, column=1, columnspan=3, pady=3)
        ttk.Label(f, text="Через (минут)").grid(row=1, column=0, sticky="w", pady=3)
        ttk.Entry(f, textvariable=mins, width=8).grid(row=1, column=1, sticky="w")
        ttk.Label(f, text="или в (ЧЧ:ММ)").grid(row=1, column=2, sticky="e", padx=6)
        ttk.Entry(f, textvariable=at, width=8).grid(row=1, column=3, sticky="w")
        ttk.Label(f, text="Повтор").grid(row=2, column=0, sticky="w", pady=3)
        ttk.Combobox(f, textvariable=rep, values=list(REPEATS.values()), state="readonly", width=18).grid(
            row=2, column=1, columnspan=2, sticky="w")
        ttk.Checkbutton(f, text="Текст — вопрос модели (она ответит голосом)", variable=ask).grid(
            row=3, column=0, columnspan=4, sticky="w", pady=3)

        def ok():
            t = text.get().strip()
            if not t:
                return
            now = datetime.now()
            when = None
            a = at.get().strip()
            if a:
                m = re.match(r"^(\d{1,2})[:.](\d{2})$", a)
                if not m or int(m.group(1)) > 23 or int(m.group(2)) > 59:
                    messagebox.showinfo("Напоминание", "Время укажите как ЧЧ:ММ, например 18:30", parent=win)
                    return
                when = now.replace(hour=int(m.group(1)), minute=int(m.group(2)), second=0, microsecond=0)
                if when <= now:
                    when += timedelta(days=1)
            else:
                try:
                    when = now + timedelta(minutes=max(0.2, float(mins.get().replace(",", "."))))
                except ValueError:
                    messagebox.showinfo("Напоминание", "Укажите число минут", parent=win)
                    return
            key = next((k for k, v in REPEATS.items() if v == rep.get()), "")
            self.add_reminder(when, t, key, ask.get())
            win.destroy()
        ttk.Button(f, text="Добавить", command=ok).grid(row=4, column=2, pady=(8, 0), sticky="e")
        ttk.Button(f, text="Отмена", command=win.destroy).grid(row=4, column=3, pady=(8, 0), sticky="e")
        ent.focus_set()
        win.bind("<Return>", lambda e: ok())

    def _rem_delete_selected(self):
        for iid in self.rem_tree.selection():
            self.cancel_reminders(int(iid))

    # ---------- память: окно редактирования ----------
    def _mem_editor(self):
        win = tk.Toplevel(self.root)
        win.title("Долгая память (одна запись на строку)")
        win.geometry("560x380")
        win.transient(self.root)
        txt = scrolledtext.ScrolledText(win, wrap="word", font=self.chat_font)
        txt.pack(fill="both", expand=True, padx=8, pady=8)
        txt.insert("1.0", "\n".join(x["t"] for x in mem_load()))

        def save():
            lines = [re.sub(r"\s+", " ", l).strip() for l in txt.get("1.0", "end").splitlines()]
            old = {norm_ru(x["t"]): x.get("ts", "") for x in mem_load()}
            items = [{"t": l[:300], "ts": old.get(norm_ru(l), datetime.now().strftime("%Y-%m-%d %H:%M"))}
                     for l in lines if l]
            with MEM_LOCK:
                _mem_save(items)
            self.status.set(f"Память сохранена: записей {len(items)}")
            win.destroy()
        bar = ttk.Frame(win)
        bar.pack(fill="x", padx=8, pady=(0, 8))
        ttk.Button(bar, text="Сохранить", command=save).pack(side="right", padx=4)
        ttk.Button(bar, text="Отмена", command=win.destroy).pack(side="right")

    def _mem_open_file(self):
        if not MEMORY_FILE.exists():
            save_json(MEMORY_FILE, [])
        self._open_path(MEMORY_FILE)

    @staticmethod
    def _open_path(path):
        try:
            if hasattr(os, "startfile"):
                os.startfile(str(path))
            else:
                subprocess.Popen(["xdg-open", str(path)])
        except Exception as e:
            messagebox.showinfo("Открыть", f"Не удалось открыть: {e}")

    # ---------- инструменты: веб, память, напоминания, файлы, буфер ----------
    def _files_base(self, cfg):
        base = Path(cfg["files_dir"] or FILES_DIR_DEFAULT)
        base.mkdir(parents=True, exist_ok=True)
        return base

    def run_extra_tool(self, cfg, name, args):
        """Возвращает строку-результат или None, если это не один из новых инструментов."""
        if name == "web_search":
            return web_search(args.get("query") or args.get("q") or args.get("text") or "", 5)
        if name == "read_webpage":
            url = str(args.get("url", "")).strip()
            if not self.confirm(cfg, f"Прочитать веб-страницу?\n\n{url}"):
                return "Пользователь отклонил"
            try:
                return read_webpage(url)
            except Exception as e:
                return f"Не удалось прочитать страницу: {e}"
        if name == "remember":
            return "Запомнено" if mem_add(args.get("text")) else "Уже было или пусто"
        if name == "forget":
            return f"Удалено записей: {mem_forget(args.get('text') or args.get('query') or '')}"
        if name == "set_reminder":
            text = str(args.get("text", "")).strip()
            if not text:
                return "Не указан текст напоминания"
            now, when = datetime.now(), None
            try:
                mins = args.get("in_minutes")
                if mins not in (None, ""):
                    mins = float(mins)
                    if not 0 < mins <= 525600:
                        return "in_minutes должно быть от 0 до 525600"
                    when = now + timedelta(minutes=mins)
            except (TypeError, ValueError):
                return "in_minutes должно быть числом"
            at = str(args.get("at", "")).strip()
            if when is None and at:
                m = re.match(r"^(\d{1,2})[:.](\d{2})$", at)
                if not m or int(m.group(1)) > 23 or int(m.group(2)) > 59:
                    return "at должно быть в формате ЧЧ:ММ"
                when = now.replace(hour=int(m.group(1)), minute=int(m.group(2)), second=0, microsecond=0)
                if when <= now:
                    when += timedelta(days=1)
            if when is None:
                return "Укажите in_minutes (через сколько минут) или at (время ЧЧ:ММ)"
            rep = str(args.get("repeat", "")).strip().lower()
            rep = rep if rep in ("daily", "weekdays", "weekly") else ""
            rid = self.add_reminder(when, text, rep, bool(args.get("ask")))
            self.log_action(name, args, f"напоминание #{rid}")
            return f"Напоминание №{rid} создано на {when:%d.%m %H:%M}" + (
                f", повтор: {repeat_label(rep).lower()}" if rep else "")
        if name == "list_reminders":
            with self._rem_lock:
                rs = list(self.reminders[:10])
            return "\n".join(f"№{r['id']}: {datetime.fromisoformat(r['when']):%d.%m %H:%M} — {r['text']}"
                             f"{' (повтор: ' + repeat_label(r['repeat']).lower() + ')' if r['repeat'] else ''}"
                             for r in rs) or "Напоминаний нет"
        if name == "cancel_reminder":
            rid = args.get("id")
            try:
                rid = int(rid) if rid not in (None, "") else None
            except (TypeError, ValueError):
                return "id должен быть числом"
            if rid is None:
                return f"Удалено напоминаний: {self.cancel_reminders()}"
            return "Удалено" if self.cancel_reminders_by_id(rid) else "Нет напоминания с таким номером"
        if name in ("list_files", "read_file", "write_file"):
            base = self._files_base(cfg)
            try:
                path = safe_path(base, args.get("path") or ".")
            except ValueError as e:
                return f"Ошибка: {e}"
            if name == "list_files":
                if not path.is_dir():
                    return "Это не папка"
                rows = []
                for e in sorted(path.iterdir())[:100]:
                    rows.append(f"{e.name}/" if e.is_dir() else f"{e.name} ({e.stat().st_size} Б)")
                return "\n".join(rows) or "Папка пуста"
            if name == "read_file":
                if not path.is_file():
                    return "Файл не найден"
                try:
                    return read_any(path, 6000)
                except Exception as e:
                    return f"Не удалось прочитать: {e}"
            if not cfg["files_write"]:
                return "Запись файлов отключена в настройках («Файлы и буфер обмена»)"
            if path.suffix.lower() in BLOCKED_WRITE_EXTS or not path.suffix:
                return "Этот тип файла записывать нельзя (скрипты и программы запрещены)"
            text = str(args.get("text", ""))
            if len(text) > 200_000:
                return "Слишком большой текст"
            old = path.read_bytes() if path.is_file() else None
            if not self.confirm(cfg, f"Записать файл в рабочую папку?\n\n{path.name}"
                                     f"{' (перезапись!)' if old is not None else ''}\n\n{text[:200]}"):
                return "Пользователь отклонил"
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8")
            self.log_action(name, {"path": path.name, "chars": len(text)}, "записано", ("file", (str(path), old)))
            return f"Файл {path.name} записан"
        if name == "set_clipboard":
            text = str(args.get("text", ""))[:5000]
            if not self.confirm(cfg, f"Скопировать в буфер обмена?\n\n{text[:200]}"):
                return "Пользователь отклонил"

            def put():
                try:
                    old = self.root.clipboard_get()
                except tk.TclError:
                    old = ""
                self.root.clipboard_clear()
                self.root.clipboard_append(text)
                return old
            old = self.call_ui(put)
            self.log_action(name, {"chars": len(text)}, "скопировано", ("clipboard", old))
            return "Скопировано в буфер обмена"
        return None

    def cancel_reminders_by_id(self, rid):
        with self._rem_lock:
            before = len(self.reminders)
            self.reminders = [r for r in self.reminders if r["id"] != rid]
            n = before - len(self.reminders)
            if n:
                self._rem_save()
        self.ui(self._rem_refresh)
        return n

    # ---------- журнал действий и отмена ----------
    def log_action(self, name, args, res, undo=None):
        if not self._act_on:
            return
        try:
            desc = self._describe(name, args) if name in COMPUTER_DEFS else \
                f"{name} {json.dumps(args, ensure_ascii=False)}"[:120]
        except Exception:
            desc = name
        e = {"ts": datetime.now().strftime("%H:%M:%S"), "name": name, "desc": desc, "res": str(res)[:120],
             "undo": undo, "undone": False}
        with self._act_lock:
            self.action_log.append(e)
            del self.action_log[:-200]
        try:
            with open(ACTIONS_LOG, "a", encoding="utf-8") as f:
                f.write(json.dumps({"ts": datetime.now().isoformat(timespec="seconds"), "action": name,
                                    "args": args, "result": e["res"]}, ensure_ascii=False) + "\n")
        except Exception:
            pass
        self.ui(self._act_refresh)

    def _act_refresh(self):
        tree = getattr(self, "act_tree", None)
        if tree is None:
            return
        tree.delete(*tree.get_children())
        with self._act_lock:
            rows = list(self.action_log[-60:])
        for i, e in enumerate(rows):
            mark = "↩ отменено" if e["undone"] else ("↩ можно" if e["undo"] else "")
            tree.insert("", 0, iid=str(i), values=(e["ts"], e["desc"], e["res"], mark))

    def act_clear(self):
        with self._act_lock:
            self.action_log.clear()
        self._act_refresh()

    def undo_last(self):
        """Отменяет последнее отменяемое действие (из рабочего потока). Возвращает сообщение."""
        with self._act_lock:
            cand = next((e for e in reversed(self.action_log) if e.get("undo") and not e["undone"]), None)
        if cand is None:
            return "Нечего отменять."
        kind, val = cand["undo"]
        try:
            if kind in ("move", "scroll", "backspace"):
                keyboard, mouse, kb, ms = self._controllers()
                self._check_failsafe()
                if kind == "move":
                    self._move(ms, *val)
                elif kind == "scroll":
                    ms.scroll(0, val)
                else:
                    for _ in range(int(val)):
                        kb.press(keyboard.Key.backspace)
                        kb.release(keyboard.Key.backspace)
                        time.sleep(0.004)
            elif kind == "clipboard":
                def put():
                    self.root.clipboard_clear()
                    self.root.clipboard_append(val)
                self.call_ui(put)
            elif kind == "file":
                path, old = Path(val[0]), val[1]
                if old is None:
                    path.unlink(missing_ok=True)
                else:
                    path.write_bytes(old)
        except ImportError:
            return "Для отмены нужен pynput."
        except Exception as e:
            return f"Не удалось отменить: {e}"
        cand["undone"] = True
        self.ui(self._act_refresh)
        return f"Отменено: {cand['desc']}"

    def undo_last_async(self):
        def work():
            self.set_status(self.undo_last())
        threading.Thread(target=work, daemon=True).start()

    # ---------- события на компьютере ----------
    def _events_tick(self):
        try:
            if self.ev_on.get():
                self._events_check()
        except Exception as e:
            self.status.set(f"События: {e}")
        finally:
            self.root.after(5000, self._events_tick)

    def _events_check(self):
        now, st = time.time(), self._ev
        watch = {w.strip().lower() for w in re.split(r"[,;]", self.ev_proc.get()) if w.strip()}
        if watch:
            cur = set()
            for p in psutil.process_iter(["name"]):
                n = (p.info.get("name") or "").lower()
                if n in watch:
                    cur.add(n)
            if st["procs"] is not None:
                for n in sorted(cur - st["procs"]):
                    self._event(f"proc:{n}", f"Запустилась программа {n}", "wave")
            st["procs"] = cur
        else:
            st["procs"] = None
        if self.ev_cpu.get():
            d = self.last_metrics
            cpu = d["cpu"] if d else 0
            st["hot"] = st["hot"] + 1 if cpu > 90 else 0
            if st["hot"] >= 6:
                st["hot"] = 0
                self._event("cpu", f"Процессор загружен на {cpu:.0f} процентов уже около полуминуты")
        if self.ev_battery.get() and hasattr(psutil, "sensors_battery"):
            b = psutil.sensors_battery()
            if b and not b.power_plugged and b.percent <= 20:
                if not st["bat_warned"]:
                    st["bat_warned"] = True
                    self._event("battery", f"Батарея разряжена: {b.percent:.0f} процентов. Подключите зарядку.")
            elif b and (b.power_plugged or b.percent > 30):
                st["bat_warned"] = False
        if self.ev_downloads.get():
            self._check_downloads(st)
        if self.ev_break.get():
            if now - st["last_break"] >= max(5, int(self._num(self.ev_break_min, 60))) * 60:
                st["last_break"] = now
                self._event("break", "Вы давно за компьютером. Сделайте небольшой перерыв.", "nod")
        else:
            st["last_break"] = now

    def _check_downloads(self, st):
        dl = Path.home() / "Downloads"
        if not dl.is_dir():
            return
        cur = {}
        try:
            for i, e in enumerate(os.scandir(dl)):
                if i > 3000:
                    break
                if e.is_file():
                    cur[e.name] = e.stat().st_size
        except OSError:
            return
        if st["dl"] is None:
            st["dl"], st["dl_pending"] = set(cur), {}
            return
        for name, size in cur.items():
            if name in st["dl"] or name.lower().endswith((".crdownload", ".part", ".tmp", ".download", ".partial")):
                continue
            if st["dl_pending"].get(name) == size and size > 0:
                st["dl"].add(name)
                st["dl_pending"].pop(name, None)
                self._event(f"dl:{name}", f"Загрузка завершена: {name}", "nod")
            else:
                st["dl_pending"][name] = size

    def _event(self, key, text, gesture=None):
        now = time.time()
        long_ = key in ("cpu", "battery", "break")
        if now - self._ev["cool"].get(key, 0) < (900 if long_ else 20):
            return
        self._ev["cool"][key] = now
        self.avatar_event("say", text=text[:80])
        if gesture:
            self.avatar_event("gesture", name=gesture)
        if self.ev_llm.get() and not self.busy:
            self.append("🔔", text, "tool")
            self.start_pipeline(text=f"[Системное событие на компьютере: {text}] Отреагируй одной короткой фразой.")
        else:
            self.say_direct(text)

    # ---------- системный трей ----------
    def _tray_apply(self):
        if self.tray_on.get():
            if self._tray is None and not self._tray_start():
                self.tray_on.set(False)
        else:
            self._tray_stop()

    def _tray_start(self):
        try:
            import pystray
            from PIL import Image, ImageDraw
        except ImportError:
            messagebox.showinfo("Трей", "Нужны пакеты pystray и pillow: скачайте «Значок в трее» на вкладке «Компоненты»\nили py -3.12 -m pip install pystray pillow")
            return False
        try:
            img = Image.open(io.BytesIO(base64.b64decode("".join(ICON_PNG_128_B64)))).convert("RGBA")
        except Exception:
            img = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
            ImageDraw.Draw(img).ellipse([4, 4, 60, 60], fill="#4dabf7")
        menu = pystray.Menu(
            pystray.MenuItem("Показать окно", lambda icon, item: self.ui(self._tray_show), default=True),
            pystray.MenuItem("Слушать / не слушать", lambda icon, item: self.ui(self._tray_toggle_listen)),
            pystray.MenuItem("⏹ Стоп", lambda icon, item: self.ui(self.interrupt)),
            pystray.MenuItem("✍ Диктовка вкл/выкл", lambda icon, item: self.ui(self._dict_toggle)),
            pystray.MenuItem("Выход", lambda icon, item: self.ui(self.quit_app)))
        self._tray = pystray.Icon("nightlord_agent", img, "Nightlord агент", menu)
        self._tray.run_detached()
        return True

    def _tray_stop(self):
        t, self._tray = self._tray, None
        if t is not None:
            try:
                t.stop()
            except Exception:
                pass
        self._tray_show()

    def _tray_show(self):
        try:
            self.root.deiconify()
            self.root.lift()
            self.root.focus_force()
        except tk.TclError:
            pass

    def _tray_toggle_listen(self):
        if self.listening or self.recording:
            self.stop_input()
        else:
            self.mode.set(MODE_VAD)
            self.start_listen()

    def _on_unmap(self, e):
        if e.widget is self.root and self._tray is not None:
            try:
                if self.root.state() == "iconic":
                    self.root.after(50, self.root.withdraw)
            except tk.TclError:
                pass

    # ---------- самопроверка ----------
    def run_selftest(self):
        if getattr(self, "_st_win", None) is not None:
            try:
                if self._st_win.winfo_exists():
                    self._st_win.lift()
                    return
            except tk.TclError:
                pass
        win = tk.Toplevel(self.root)
        win.title("Проверка системы")
        win.geometry("860x440")
        self._st_win = win
        cols = [("name", "Проверка", 170), ("res", "Результат", 90), ("ms", "Время", 70), ("info", "Подробности", 500)]
        tree = ttk.Treeview(win, columns=[c[0] for c in cols], show="headings", height=12)
        for k, t, w in cols:
            tree.heading(k, text=t)
            tree.column(k, width=w, anchor="w")
        tree.pack(fill="both", expand=True, padx=8, pady=8)
        for tag, key in (("ok", "ok"), ("bad", "bad"), ("warn", "tool")):
            tree.tag_configure(tag, foreground=self.pal[key])
        summary = tk.StringVar(value="Проверяю…")
        ttk.Label(win, textvariable=summary).pack(anchor="w", padx=10)
        beep = tk.BooleanVar(value=False)
        bar = ttk.Frame(win)
        bar.pack(fill="x", padx=8, pady=8)
        ttk.Checkbutton(bar, text="Проиграть тестовый звук", variable=beep).pack(side="left")
        rows = []

        def copy():
            self.root.clipboard_clear()
            self.root.clipboard_append("\n".join(rows))
            summary.set("Отчёт скопирован в буфер обмена")

        def start():
            tree.delete(*tree.get_children())
            rows.clear()
            summary.set("Проверяю…")
            threading.Thread(target=self._selftest_worker, args=(tree, summary, rows, beep.get()), daemon=True).start()
        ttk.Button(bar, text="Повторить", command=start).pack(side="right", padx=4)
        ttk.Button(bar, text="Скопировать отчёт", command=copy).pack(side="right")
        start()

    def _selftest_worker(self, tree, summary, rows, beep):
        try:
            cfg = self.call_ui(self._make_cfg)
        except Exception as e:
            self.ui(summary.set, f"Не удалось прочитать настройки: {e}")
            return
        stats = {"ok": 0, "bad": 0, "warn": 0}
        marks = {"ok": "✓ ок", "bad": "✗ ошибка", "warn": "! внимание"}

        def add(name, status, ms, info):
            stats[status] += 1
            rows.append(f"[{status.upper()}] {name}: {info} ({ms:.0f} мс)")
            self.ui(lambda: tree.winfo_exists() and tree.insert(
                "", "end", values=(name, marks[status], f"{ms:.0f} мс", info), tags=(status,)))

        def run(name, fn):
            t0 = time.perf_counter()
            try:
                status, info = fn()
            except Exception as e:
                status, info = "bad", str(e)[:300]
            add(name, status, (time.perf_counter() - t0) * 1000, info)

        def st_mic():
            if self.stream is not None:
                return "warn", f"микрофон сейчас занят записью (уровень {self.level:.3f}), проверка пропущена"
            idx = cfg["mic_index"]
            data = sd.rec(int(0.6 * SAMPLE_RATE), samplerate=SAMPLE_RATE, channels=1, device=idx, dtype="float32")
            sd.wait()
            rms = float(np.sqrt(np.mean(data ** 2)))
            nm = sd.query_devices(idx)["name"] if idx is not None else "по умолчанию"
            if rms < 1e-6:
                return "warn", f"{nm}: полная тишина — микрофон выключен или не тот источник"
            return "ok", f"{nm}: уровень {rms:.4f} (порог VAD сейчас {cfg['vad_thr']:.3f})"

        def st_out():
            dev = sd.query_devices(kind="output")
            if beep:
                t = np.linspace(0, 0.3, int(24000 * 0.3), False)
                self._play((0.15 * np.sin(2 * np.pi * 440 * t) * self._volume).astype("float32"), 24000)
                sd.wait()
            return "ok", f"{dev['name']}" + (", сигнал проигран" if beep else "")

        def st_whisper():
            self._get_whisper(cfg["w_model"], cfg["w_device"], status=False)
            self._run_whisper(cfg["w_model"], cfg["w_device"], np.zeros(SAMPLE_RATE, dtype="float32"), None, False)
            return "ok", f"модель {cfg['w_model']}, устройство {cfg['w_device']}"

        def st_lm():
            r = requests.get(f"{cfg['lm_url']}/v1/models", timeout=4)
            r.raise_for_status()
            ids = [m.get("id") for m in r.json().get("data", [])]
            if not ids:
                return "warn", "сервер отвечает, но модели не загружены"
            body = {"messages": [{"role": "user", "content": "Ответь одним словом: ок"}], "max_tokens": 24,
                    "temperature": 0, "stream": False}
            if cfg["lm_model"]:
                body["model"] = cfg["lm_model"]
            r = requests.post(f"{cfg['lm_url']}/v1/chat/completions", json=body, timeout=180)
            r.raise_for_status()
            ans = re.sub(r"<think>.*?</think>", "", r.json()["choices"][0]["message"].get("content") or "",
                         flags=re.S).strip()[:40]
            miss = cfg["lm_model"] and cfg["lm_model"] not in ids
            return ("warn" if miss else "ok"), (f"модели «{cfg['lm_model']}» нет в списке {ids[:3]}" if miss
                                                else f"{cfg['lm_model'] or ids[0]} ответила: «{ans}»")

        def st_vb():
            r = requests.get(f"{cfg['vb_url']}/profiles", timeout=4)
            r.raise_for_status()
            if cfg["profile_name"] and cfg["profile_name"] not in self.profile_ids:
                return "warn", f"голос «{cfg['profile_name']}» не найден — нажмите ⟳ рядом с голосом"
            audio = self._synth(dict(cfg, vb_method=cfg["vb_method"]), "Проверка связи.")
            if audio is None:
                return "warn", "Voicebox ответил, но звука нет"
            data, sr = audio
            if data is None:
                return "ok", f"метод /speak: Voicebox играет сам (≈{sr:.1f} с), голос «{cfg['profile_name']}»"
            if beep:
                self._play(np.clip(data * self._volume, -1, 1), sr)
                sd.wait()
            return "ok", f"синтез {len(data) / sr:.1f} с звука, голос «{cfg['profile_name']}», движок {cfg['engine']}"

        def st_screen():
            try:
                from PIL import ImageGrab
            except ImportError:
                return "warn", "Pillow не установлен — экран и спрайты недоступны"
            size = ImageGrab.grab().size
            try:
                import pynput  # noqa: F401
                ctl = "pynput есть"
            except ImportError:
                ctl = "pynput не установлен (мышь и клавиатура недоступны)"
            return "ok", f"скриншот {size[0]}×{size[1]}, {ctl}"

        def st_web():
            res = web_search("погода", 2, timeout=8)
            if res.startswith(("Поиск недоступен", "Ничего")):
                return "warn", res
            return "ok", "DuckDuckGo отвечает: " + res.splitlines()[0][:80]

        def st_files():
            base = self._files_base(cfg)
            probe = base / ".write_test"
            probe.write_text("x")
            probe.unlink()
            return "ok", f"{base} (запись {'разрешена' if cfg['files_write'] else 'для модели отключена'})"

        def st_misc():
            return "ok", (f"память: {len(mem_load())} записей; напоминаний: {len(self.reminders)}; "
                          f"3D-сервер: {'работает ' + self.avatar3d.url() if self.avatar3d.is_open else 'выключен'}")

        for name, fn in (("Микрофон", st_mic), ("Динамики", st_out), ("Whisper (STT)", st_whisper),
                         ("LM Studio", st_lm), ("Voicebox (TTS)", st_vb), ("Экран и управление", st_screen),
                         ("Веб-поиск", st_web), ("Папка файлов", st_files), ("Память и аватар", st_misc)):
            self.ui(summary.set, f"Проверяю: {name}…")
            run(name, fn)
        line = f"Готово: ✓ {stats['ok']}   ! {stats['warn']}   ✗ {stats['bad']}"
        self.ui(summary.set, line)
        self.set_status(line)

