# ----- словарь произношения -----
_pron_cache = {"key": None, "rx": None}


def apply_pron(text, table):
    """Заменяет слова в тексте для озвучки (регистр не важен, только целые слова)."""
    if not table or not text:
        return text
    key = tuple(sorted(table.items()))
    if _pron_cache["key"] != key:
        keys = sorted((k for k in table if k.strip()), key=len, reverse=True)
        rx = re.compile(r"(?<!\w)(" + "|".join(re.escape(k) for k in keys) + r")(?!\w)", re.I) if keys else None
        _pron_cache.update(key=key, rx=rx)
    rx = _pron_cache["rx"]
    if rx is None:
        return text
    low = {k.lower(): v for k, v in table.items()}
    return rx.sub(lambda m: low.get(m.group(1).lower(), m.group(1)), text)


def pron_to_text(table):
    return "\n".join(f"{k} = {v}" for k, v in table.items())


def pron_from_text(text):
    out = {}
    for line in (text or "").splitlines():
        if "=" in line:
            k, v = line.split("=", 1)
            if k.strip() and v.strip():
                out[k.strip()] = v.strip()
    return out


# ----- шумоподавление (спектральное вычитание, только numpy) -----
def denoise(audio, sr=16000, strength=1.0):
    x = np.asarray(audio, dtype=np.float32).flatten()
    n_fft, hop = 512, 128
    if len(x) < n_fft * 4:
        return x
    win = np.hanning(n_fft).astype(np.float32)
    pad = np.pad(x, (n_fft, n_fft))
    nfr = 1 + (len(pad) - n_fft) // hop
    idx = np.arange(n_fft)[None, :] + hop * np.arange(nfr)[:, None]
    spec = np.fft.rfft(pad[idx] * win, axis=1)
    mag = np.abs(spec)
    noise = np.percentile(mag, 15, axis=0)       # шум по каждой частоте: тихие моменты записи
    gain = np.clip(1.0 - strength * 1.6 * noise / (mag + 1e-8), 0.1, 1.0)
    k = np.ones(5, dtype=np.float32) / 5          # сглаживание по времени против «музыкального» шума
    gain = np.apply_along_axis(lambda c: np.convolve(c, k, mode="same"), 0, gain)
    frames = np.fft.irfft(spec * gain, n=n_fft, axis=1).astype(np.float32) * win
    out = np.zeros(len(pad), dtype=np.float32)
    wsum = np.zeros(len(pad), dtype=np.float32)
    w2 = win * win
    for i in range(nfr):
        s = i * hop
        out[s:s + n_fft] += frames[i]
        wsum[s:s + n_fft] += w2
    out = out / np.maximum(wsum, 1e-6)
    return out[n_fft:n_fft + len(x)].astype(np.float32)


# ----- виземы: форма рта по звуку (приближённо) -----
def make_visemes(data, sr):
    """Массив (n, 5): веса aa, ih, ou, ee, oh с шагом ENV_DT, уже умноженные на громкость.
    Оценка по долям энергии в полосах ~F1/F2 — это эвристика, а не распознавание фонем."""
    x = np.asarray(data, dtype=np.float32)
    if x.ndim > 1:
        x = x.mean(axis=1)
    env = make_envelope(x, sr)
    n = len(env)
    hop = max(1, int(sr * ENV_DT))
    out = np.zeros((n, 5), dtype=np.float32)
    if n == 0 or float(env.max()) <= 0:
        return out
    size = hop * 2
    win = np.hanning(size).astype(np.float32)
    freqs = np.fft.rfftfreq(size, 1.0 / sr)
    bands = [(freqs >= 150) & (freqs < 550), (freqs >= 550) & (freqs < 1400), (freqs >= 1400) & (freqs < 3800)]
    for i in range(n):
        seg = x[i * hop:i * hop + size]
        if len(seg) < size:
            seg = np.pad(seg, (0, size - len(seg)))
        mag = np.abs(np.fft.rfft(seg * win)) ** 2
        e = np.array([mag[b].sum() for b in bands]) + 1e-9
        r = e / e.sum()
        low, mid, hi = float(r[0]), float(r[1]), float(r[2])
        w = np.array([mid * (1.5 if mid > low * 2.5 else .4), hi * .55, low * (1.3 if low > mid * .8 else .5),
                      hi * .85, low * .55 + mid * .35], dtype=np.float32)
        s = float(w.sum())
        out[i] = (w / s if s > 0 else w) * float(env[i])
    return np.clip(out, 0, 1)


# ----- сценарии -----
def parse_macro_line(line):
    """Строка сценария -> шаг или None. Примеры: «открыть блокнот», «громкость 60», «режим Переводчик»."""
    raw = (line or "").strip()
    if not raw or raw.startswith("#"):
        return None
    t = norm_ru(raw)
    m = re.match(r"^(?:открой|открыть|запусти|запустить) (?:программу )?(.+)$", t)
    if m and not re.match(r"^(?:сайт|ссылку|страницу)\b", m.group(1)):
        return {"type": "app", "name": m.group(1).strip()}
    m = re.search(r"(https?://\S+)", raw)
    if m and re.match(r"^(?:ссылка|сайт|открой|открыть|страница)", t):
        return {"type": "url", "url": m.group(1)}
    m = re.match(r"^громкость (\d{1,3})", t)
    if m:
        return {"type": "volume", "value": max(0, min(200, int(m.group(1))))}
    m = re.match(r"^режим (.+)$", t)
    if m:
        return {"type": "mode", "name": m.group(1).strip()}
    m = re.match(r"^озвучка (вкл|выкл)", t)
    if m:
        return {"type": "tts", "on": m.group(1) == "вкл"}
    m = re.match(r"^(?:сказать|скажи|говорить) (.+)$", raw, re.I)
    if m:
        return {"type": "say", "text": m.group(1).strip()}
    m = re.match(r"^(?:ждать|жди|пауза) (\d+(?:[.,]\d+)?)", t)
    if m:
        return {"type": "wait", "seconds": min(10.0, float(m.group(1).replace(",", ".")))}
    m = re.match(r"^(?:спросить|спроси|вопрос) (.+)$", raw, re.I)
    if m:
        return {"type": "ask", "text": m.group(1).strip()}
    return {"type": "unknown", "text": raw}


def parse_macro(text):
    return [s for s in (parse_macro_line(l) for l in (text or "").splitlines()) if s]


# ----- диктовка -----
_PUNCT = [("точка с запятой", ";"), ("вопросительный знак", "?"), ("восклицательный знак", "!"),
          ("открыть скобку", "("), ("закрыть скобку", ")"), ("запятая", ","), ("точка", "."),
          ("двоеточие", ":"), ("многоточие", "…"), ("тире", " —")]
DICT_STOP_RE = re.compile(r"^(?:закончи|закончить|конец|останови|выключи|отключи|прекрати|стоп)\s+диктовк\w*$"
                          r"|^диктовка\s+(?:закончена|стоп|все|конец)$")


def dictation_text(text, last=None):
    """(строка для печати, последний напечатанный символ). Разговорные «запятая», «точка», «новая строка»…"""
    t = " " + re.sub(r"\s+", " ", text.strip()) + " "
    newline = None
    for word, sym in [("новый абзац", "\n\n"), ("новая строка", "\n"), ("с новой строки", "\n")]:
        t = re.sub(rf"(?i)\s{word}[\s,.]", lambda m, s=sym: f" \x00{len(s)}\x00 ", t)
    for word, sym in _PUNCT:
        t = re.sub(rf"(?i)[\s,]{word}(?=[\s,.!?]|$)", lambda m, s=sym: s + " ", t)
    t = re.sub(r"\x00(\d)\x00", lambda m: "\n" * int(m.group(1)), t)
    t = re.sub(r"[ \t]+([,.!?:;…)])", r"\1", t)
    t = re.sub(r"[ \t]{2,}", " ", t)
    t = re.sub(r" *\n *", "\n", t).strip(" ")
    if not t:
        return "", last
    cap = last is None or last in ".!?\n"
    if cap:
        for i, ch in enumerate(t):
            if ch.isalpha():
                t = t[:i] + ch.upper() + t[i + 1:]
                break
    s = t if t.endswith("\n") else t + " "
    return s, s[-1] if s.strip() == "" and s.endswith("\n") else (s.rstrip(" ")[-1:] or s[-1])


# ----- резервная копия -----
BACKUP_SECRET_RE = re.compile(r"(?:key|token|pass|secret|cookie|auth|sub_url|servers|link|webhook|bearer)", re.I)
BACKUP_PLUGIN_RE = re.compile(r"^plugins/data/([\w.-]+)/([\w.-]+\.(?:json|txt))$")
BACKUP_AVATAR_RE = re.compile(r"^avatar/([\w.-]+\.(?:png|jpg|jpeg|gif|webp))$", re.I)
BACKUP_MAX_FILE = 2 * 1024 * 1024


def _scrub(obj):
    """Пустые значения у ключей вида key/token/password/ссылки подписок — для копии, которой можно поделиться."""
    if isinstance(obj, dict):
        return {k: ("" if BACKUP_SECRET_RE.search(str(k)) and not isinstance(v, bool) else _scrub(v)) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_scrub(x) for x in obj]
    return obj


def backup_make(dest, secrets=True):
    """Настройки программы + настройки всех плагинов (plugins/data/*/*.json|txt) + свои спрайты аватара.
    secrets=False — без ключей, токенов, паролей и ссылок подписок. Код плагинов в копию не входит."""
    import zipfile
    n = 0

    def put(z, p, name):
        nonlocal n
        if secrets or not name.endswith(".json"):
            z.write(p, name)
        else:
            try:
                z.writestr(name, json.dumps(_scrub(json.loads(p.read_text(encoding="utf-8"))), ensure_ascii=False, indent=1))
            except (OSError, ValueError):
                return
        n += 1

    with zipfile.ZipFile(dest, "w", zipfile.ZIP_DEFLATED) as z:
        for name in BACKUP_FILES:
            p = BASE / name
            if p.is_file() and (secrets or name != "plugins.json"):
                put(z, p, name)
        data = PLUGINS_DIR / "data"
        if data.is_dir():
            for d in sorted(data.iterdir()):
                if not d.is_dir():
                    continue
                for f in sorted(d.iterdir()):
                    name = f"plugins/data/{d.name}/{f.name}"
                    if f.is_file() and BACKUP_PLUGIN_RE.match(name) and f.stat().st_size <= BACKUP_MAX_FILE:
                        put(z, f, name)
        if AVATAR_DIR.is_dir():
            for f in sorted(AVATAR_DIR.iterdir()):
                if f.is_file() and BACKUP_AVATAR_RE.match(f"avatar/{f.name}") and f.stat().st_size <= 5 * BACKUP_MAX_FILE:
                    put(z, f, f"avatar/{f.name}")
        z.writestr("backup_info.txt", f"Nightlord агент backup {datetime.now():%Y-%m-%d %H:%M:%S}"
                                      f"{'' if secrets else ' (без ключей и паролей)'}\n")
    return n


def backup_restore(src):
    """Восстанавливает только известные файлы (без путей наружу). Старые версии сохраняет как *.bak.
    Код плагинов не восстанавливается — только их настройки."""
    import zipfile
    restored = []
    with zipfile.ZipFile(src) as z:
        infos = {i.filename: i for i in z.infolist()}
        for name in BACKUP_FILES:
            if name in infos and "/" not in name and "\\" not in name:
                dst = BASE / name
                if dst.is_file():
                    shutil.copyfile(dst, str(dst) + ".bak")
                dst.write_bytes(z.read(name))
                restored.append(name)
        for name, info in infos.items():
            if info.file_size > 5 * BACKUP_MAX_FILE:
                continue
            if BACKUP_PLUGIN_RE.match(name):
                dst = BASE / name
            elif BACKUP_AVATAR_RE.match(name):
                dst = BASE / name
            else:
                continue
            dst.parent.mkdir(parents=True, exist_ok=True)
            if dst.is_file():
                shutil.copyfile(dst, str(dst) + ".bak")
            data = z.read(name)
            if name.endswith(".json"):
                try:                      # пустые значения из «безопасной» копии не затирают то, что уже введено
                    new = json.loads(data.decode("utf-8"))
                    old = json.loads(dst.read_text(encoding="utf-8")) if dst.is_file() else {}
                    if isinstance(new, dict) and isinstance(old, dict):
                        for k, v in new.items():
                            if v == "" and old.get(k):
                                new[k] = old[k]
                        data = json.dumps(new, ensure_ascii=False, indent=1).encode("utf-8")
                except (ValueError, OSError):
                    pass
            dst.write_bytes(data)
            restored.append(name)
    return restored


# ----- обновление из файла -----
def ver_key(v):
    """'2026.10.20' -> (2026, 10, 20); нечисловое -> ()."""
    return tuple(int(x) for x in re.findall(r"\d+", str(v or "")))


def update_inspect(src):
    """Проверяет файл обновления (.py или .zip с voice_agent.py). -> dict(code, version, extras, error)."""
    import zipfile
    src = Path(src)
    extras = {}
    try:
        if src.suffix.lower() == ".zip":
            with zipfile.ZipFile(src) as z:
                cands = [i for i in z.infolist() if not i.is_dir() and Path(i.filename).name == "voice_agent.py"]
                if not cands:
                    return {"error": "в архиве нет voice_agent.py"}
                main = min(cands, key=lambda i: len(i.filename))
                if main.file_size > 40 * 1024 * 1024:
                    return {"error": "voice_agent.py в архиве слишком большой"}
                code = z.read(main)
                prefix = main.filename[:-len("voice_agent.py")]
                for i in z.infolist():
                    nm = Path(i.filename).name
                    if (not i.is_dir() and nm in UPDATE_EXTRA_FILES and i.filename == prefix + nm
                            and i.file_size < 5 * 1024 * 1024):
                        extras[nm] = z.read(i)
        elif src.suffix.lower() == ".py":
            if src.stat().st_size > 40 * 1024 * 1024:
                return {"error": "файл слишком большой"}
            code = src.read_bytes()
        else:
            return {"error": "нужен файл .zip с агентом или voice_agent.py"}
    except (OSError, zipfile.BadZipFile) as e:
        return {"error": f"файл не открылся: {e}"}
    try:
        text = code.decode("utf-8")
        compile(text, "voice_agent.py", "exec")
    except (UnicodeDecodeError, SyntaxError, ValueError) as e:
        return {"error": f"это не рабочий voice_agent.py ({type(e).__name__})"}
    m = re.search(r'^APP_VERSION\s*=\s*"([^"]+)"', text, re.M)
    if not m or "class App(" not in text or "BUNDLED_PLUGINS" not in text:
        return {"error": "файл не похож на Nightlord агент (нет версии программы или основных блоков)"}
    return {"code": code, "version": m.group(1), "extras": extras}


UPD_REPO_RE = re.compile(r"^[A-Za-z0-9_.-]{1,100}/[A-Za-z0-9_.-]{1,100}$")
UPD_BRANCH_RE = re.compile(r"^[A-Za-z0-9_./-]{1,100}$")
UPD_MAX = 60 * 1024 * 1024


def update_download(repo, branch="main", token="", dest=None):
    """Скачивает zip ветки с GitHub в файл dest (или во временный). Сначала напрямую, потом через веб-прокси агента.
    Без токена — публичный адрес github.com, с токеном — API (подходит для приватных репозиториев)."""
    repo, branch, token = str(repo).strip(), str(branch or "main").strip(), str(token or "").strip()
    if not UPD_REPO_RE.match(repo):
        raise RuntimeError("репозиторий нужно указать как «владелец/имя», например nightlord/nightlord-agent")
    if not UPD_BRANCH_RE.match(branch) or ".." in branch:
        raise RuntimeError("неверное имя ветки")
    if token:
        url = f"https://api.github.com/repos/{repo}/zipball/{branch}"
        headers = {"Accept": "application/vnd.github+json", "Authorization": f"Bearer {token}", "User-Agent": UA}
    else:
        url = f"https://github.com/{repo}/archive/refs/heads/{branch}.zip"
        headers = {"User-Agent": UA}
    dest = Path(dest) if dest else Path(tempfile.gettempdir()) / "nightlord_update.zip"
    last = None
    for px in [None] + ([NET_PROXY["web"]] if NET_PROXY.get("web") else []):
        try:
            s = requests.Session()
            s.trust_env = False
            with s.get(url, headers=headers, proxies=px, timeout=(10, 40), stream=True) as r:
                if r.status_code == 404:
                    raise RuntimeError("репозиторий или ветка не найдены (для приватного репозитория нужен токен)")
                if r.status_code in (401, 403):
                    raise RuntimeError("доступ запрещён: токен не принят или нет права чтения, либо исчерпан лимит запросов")
                if r.status_code >= 400:
                    raise RuntimeError(f"GitHub ответил кодом {r.status_code}")
                n = 0
                tmp = dest.with_suffix(".part")
                try:
                    with open(tmp, "wb") as f:
                        for chunk in r.iter_content(65536):
                            n += len(chunk)
                            if n > UPD_MAX:
                                raise RuntimeError("архив слишком большой")
                            f.write(chunk)
                    os.replace(tmp, dest)
                finally:
                    if tmp.exists():
                        try:
                            tmp.unlink()
                        except OSError:
                            pass
                return dest
        except requests.RequestException as e:
            last = RuntimeError(explain_proxy_error(e))
    raise last or RuntimeError("не удалось скачать")


def update_apply(info, base=None):
    """Заменяет voice_agent.py (старый — в voice_agent.py.bak) и вспомогательные файлы рядом с ним. -> список имён."""
    base = Path(base or BASE)
    done = []
    items = [("voice_agent.py", info["code"])] + sorted(info.get("extras", {}).items())
    for name, data in items:
        dst = base / name
        tmp = base / f".{name}.new"
        tmp.write_bytes(data)
        try:
            if dst.is_file():
                shutil.copyfile(dst, str(dst) + ".bak")
            os.replace(tmp, dst)
        finally:
            if tmp.exists():
                try:
                    tmp.unlink()
                except OSError:
                    pass
        done.append(name)
    return done


# ----- подбор голосовых команд, часть 2 -----
VERB_KEYS = {"прочитай": "read", "озвучь": "read", "переведи": "translate", "объясни": "explain",
             "перескажи": "summary", "исправь": "fix"}


def match_hot2(text):
    """Команды: диктовка, сценарии, выделенное/буфер/экран. None — не подходит."""
    t = norm_ru(text)
    if re.match(r"^(?:включи |начни |запусти |давай )?(?:режим )?диктовк\w+$|^диктуй$|^начни диктовать$|^включи диктовать$", t) \
            and not DICT_STOP_RE.match(t):
        return "dict_on", None
    if DICT_STOP_RE.match(t):
        return "dict_off", None
    m = re.match(r"^(?:запусти |включи |выполни |запустить )?сценарий (.{2,})$", t)
    if m:
        return "macro", m.group(1).strip()
    m = re.match(r"^(прочитай|озвучь|переведи|объясни|перескажи|исправь)(?: ошибки в)?(?: мне)? (?:этот |тот )?"
                 r"(выделенн\w+|скопированн\w+|буфер\w*|содержимое буфера)(?: обмена)?(?: текст| фрагмент)?$", t)
    if m:
        return "selection", (VERB_KEYS[m.group(1)], "sel" if m.group(2).startswith("выделен") else "clip")
    if re.match(r"^(?:объясни|расскажи|скажи|опиши)(?: мне)? что (?:там )?(?:происходит )?на экране$|"
                r"^что (?:там )?на экране$|^посмотри на экран$|^что ты видишь на экране$", t):
        return "screen", "explain"
    if re.match(r"^переведи(?: мне)?(?: то)? что на экране$|^переведи экран$", t):
        return "screen", "translate"
    return None


class Extras2Mixin:
    """Часть 2: быстрый ответ и прогрев, словарь произношения, подсказка Whisper, шумоподавление,
    «объясни выделенное/экран», диктовка в активное окно, сценарии, резервная копия, виземы."""

    # ---------- переменные ----------
    def _init_extra2_vars(self):
        B, S = tk.BooleanVar, tk.StringVar
        self.fast_first = B(value=True)
        self.warm_srv = B(value=True)
        self.pron_on = B(value=True)
        self.w_hint = S(value="")
        self.hint_auto = B(value=True)
        self.denoise_on = B(value=False)
        self.auto_thr = B(value=False)
        self.sel_on = B(value=True)
        self.dict_cmd = B(value=False)
        self.macro_on = B(value=True)
        self.macro_confirm = B(value=True)
        self.avatar_vis = B(value=True)
        self.upd_repo = S(value="")          # «владелец/имя» репозитория GitHub с обновлениями
        self.upd_branch = S(value="main")
        self.upd_token = S(value="")         # нужен только для приватного репозитория
        self.upd_auto = B(value=False)       # раз в сутки при запуске спрашивать о новой версии
        self.upd_last = S(value="")
        self.dictating = B(value=False)      # намеренно не сохраняется между запусками
        self._pron, self._pron_on = {}, True
        self._vis_on = True
        self._dictating = False
        self._dict_last = None
        self._auto_thr_on = False
        self._rms_hist = collections.deque(maxlen=100)
        self._rms_n = 0
        self._floor = 0.0
        self._skip_save = False
        for var, attr in ((self.pron_on, "_pron_on"), (self.avatar_vis, "_vis_on"),
                          (self.dictating, "_dictating"), (self.auto_thr, "_auto_thr_on")):
            var.trace_add("write", lambda *a, v=var, n=attr: setattr(self, n, bool(v.get())))
        self.dictating.trace_add("write", lambda *a: self._dict_changed())

    def _extra2_setting_vars(self):
        return {k: getattr(self, k) for k in (
            "fast_first", "warm_srv", "pron_on", "w_hint", "hint_auto", "denoise_on", "auto_thr", "sel_on",
            "dict_cmd", "macro_on", "macro_confirm", "avatar_vis", "upd_repo", "upd_branch", "upd_token", "upd_auto", "upd_last")}

    def _extras2_start(self):
        self._pron_on = bool(self.pron_on.get())
        self._vis_on = bool(self.avatar_vis.get())
        self._auto_thr_on = bool(self.auto_thr.get())
        self.pron_reload()
        load_dict_or_create(MACROS_FILE, DEFAULT_MACROS)
        if self.warm_srv.get():
            self.root.after(2500, lambda: self.warm_servers(quiet=True))
        if self.upd_auto.get() and self.upd_repo.get().strip() and not getattr(sys, "frozen", False):
            self.root.after(25000, lambda: self.check_github_update(auto=True))

    def _cfg2(self):
        return dict(fast_first=self.fast_first.get(), w_prompt=self.whisper_prompt(), denoise=self.denoise_on.get(),
                    sel_on=self.sel_on.get(), dict_cmd=self.dict_cmd.get(), macro_on=self.macro_on.get(),
                    macro_confirm=self.macro_confirm.get())

    # ---------- 1. прогрев сервисов ----------
    def warm_servers(self, quiet=False):
        """Фоном «будит» Voicebox (один короткий синтез, звук не играет) и LM Studio (запрос на 1 токен)."""
        try:
            cfg = self._make_cfg()
        except Exception:
            return

        def work():
            res = []
            try:
                if cfg["profile"] and cfg["vb_method"] != "speak":
                    self._vb_generate(cfg, "Привет.")
                    res.append("голос")
            except Exception as e:
                res.append(f"голос: ошибка ({str(e)[:60]})")
            try:
                body = {"messages": [{"role": "user", "content": "Привет"}], "max_tokens": 1, "stream": False,
                        "temperature": 0}
                if cfg["lm_model"]:
                    body["model"] = cfg["lm_model"]
                r = requests.post(f"{cfg['lm_url']}/v1/chat/completions", json=body, timeout=120)
                r.raise_for_status()
                res.append("модель")
            except Exception as e:
                res.append(f"модель: ошибка ({str(e)[:60]})")
            self.set_status("Прогрев: " + ", ".join(res))
            if not quiet:
                self.append("Прогрев", ", ".join(res), "tool")
        threading.Thread(target=work, daemon=True).start()

    # ---------- 2. словарь произношения ----------
    def pron_reload(self):
        t = load_dict_or_create(PRON_FILE, DEFAULT_PRON)
        self._pron = {str(k): str(v) for k, v in t.items()} if isinstance(t, dict) else {}

    def edit_pron(self):
        def save(text):
            save_json(PRON_FILE, pron_from_text(text))
            self.pron_reload()

        def sample(entry, win):
            self.pron_reload()
            if entry.strip():
                self.say_direct(entry.strip())
        self._edit_dialog("Словарь произношения",
                          "Одна строка — одно правило: «как написано = как произносить». Регистр не важен, "
                          "заменяются только целые слова. Меняется только озвучка, в чате текст прежний.",
                          pron_to_text(load_dict_or_create(PRON_FILE, DEFAULT_PRON)), save,
                          reset=lambda: pron_to_text(DEFAULT_PRON), sample=sample)

    # ---------- 3. подсказка для Whisper ----------
    def whisper_prompt(self):
        parts = [self.w_hint.get().strip()]
        if self.hint_auto.get():
            names = parse_wake_words(self.wake_words.get())
            try:
                names += list(load_dict_or_create(APPS_FILE, DEFAULT_APPS))
            except Exception:
                pass
            names += list(self.profiles)[:8]
            parts.append(", ".join(dict.fromkeys(n for n in names if n)))
        s = ". ".join(p for p in parts if p)
        return ("Термины: " + s)[:220] if s else ""

    # ---------- общее окно-редактор ----------
    def _edit_dialog(self, title, hint, text, on_save, reset=None, sample=None, extra=()):
        win = tk.Toplevel(self.root)
        win.title(title)
        win.geometry("600x460")
        ttk.Label(win, text=hint, wraplength=560, justify="left", foreground="#777").pack(anchor="w", padx=10,
                                                                                         pady=(8, 2))
        t = scrolledtext.ScrolledText(win, height=14, wrap="word")
        t.pack(fill="both", expand=True, padx=10, pady=4)
        t.insert("1.0", text)
        bar = ttk.Frame(win)
        bar.pack(fill="x", padx=10, pady=8)

        def do_save():
            on_save(t.get("1.0", "end"))
            self.set_status(f"{title}: сохранено")
        ttk.Button(bar, text="Сохранить", command=do_save).pack(side="left")
        if reset:
            ttk.Button(bar, text="Сбросить к стандартному",
                       command=lambda: (t.delete("1.0", "end"), t.insert("1.0", reset()))).pack(side="left", padx=6)
        if sample:
            e = tk.StringVar(value="Запускаю LM Studio на GPU")
            ttk.Entry(bar, textvariable=e, width=26).pack(side="left", padx=(14, 2))
            ttk.Button(bar, text="Проверить на слух",
                       command=lambda: (do_save(), sample(e.get(), win))).pack(side="left")
        ttk.Button(bar, text="Закрыть", command=win.destroy).pack(side="right")
        return win

    # ---------- 7. выделенный текст, буфер, экран ----------
    def hot2_dispatch(self, cfg, text):
        m = match_hot2(text)
        if not m:
            return None
        kind, arg = m
        try:
            if kind == "dict_on":
                if not cfg["dict_cmd"]:
                    return ("say", "Голосовое включение диктовки выключено в настройках. Включите галочку на вкладке «Функции».")
                return self._dict_begin()
            if kind == "dict_off":
                return ("say", "Диктовка и так выключена.")
            if kind == "macro":
                if not cfg["macro_on"]:
                    return None
                return self._macro_voice(cfg, arg)
            if kind == "selection":
                if not cfg["sel_on"]:
                    return None
                return self._text_job(cfg, *arg)
            if kind == "screen":
                if not cfg["sel_on"]:
                    return None
                return self._screen_job(cfg, arg)
        except Exception as e:
            return ("say", f"Не получилось: {e}")
        return None

    def _get_selection(self):
        """Копирует выделенное в активном окне (Ctrl+C), читает буфер и возвращает прежнее содержимое буфера."""
        U = self.call_ui
        keyboard, mouse, kb, ms = self._controllers()

        def getclip():
            try:
                return self.root.clipboard_get()
            except tk.TclError:
                return None

        def setclip(s):
            self.root.clipboard_clear()
            if s is not None:
                self.root.clipboard_append(s)
        old = U(getclip)
        token = f"__va_{time.time_ns()}__"
        U(lambda: setclip(token))
        got = None
        try:
            time.sleep(0.05)
            with kb.pressed(keyboard.Key.ctrl):
                kb.press("c")
                kb.release("c")
            for _ in range(14):
                time.sleep(0.05)
                v = U(getclip)
                if v and v != token:
                    got = v
                    break
        finally:
            U(lambda: setclip(old))
        return got

    TEXT_PROMPTS = {
        "explain": "Объясни простыми словами, о чём этот текст (3–5 предложений):\n\n{t}",
        "summary": "Перескажи кратко (2–4 предложения):\n\n{t}",
        "fix": "Исправь орфографию и пунктуацию, смысл не меняй. Выведи только исправленный текст:\n\n{t}",
        "translate": "Переведи на {lang}. Выведи только перевод:\n\n{t}",
    }

    def _text_job(self, cfg, verb, src):
        U = self.call_ui
        if src == "sel":
            text = self._get_selection()
            empty = "Ничего не выделено. Выделите текст в окне и повторите."
        else:
            try:
                text = U(lambda: self.root.clipboard_get())
            except tk.TclError:
                text = None
            empty = "Буфер обмена пуст или в нём не текст."
        if not text or not text.strip():
            return ("say", empty)
        text = text.strip()[:6000]
        self.append("📋", f"{'выделено' if src == 'sel' else 'буфер'}: {text[:200]}", "tool")
        if verb == "read":
            return ("say", text[:1500])
        cyr = sum(1 for c in text if "а" <= c.lower() <= "я" or c.lower() == "ё")
        lang = "английский" if cyr > len(text) * .3 else "русский"
        return ("llm", self.TEXT_PROMPTS[verb].format(t=text, lang=lang), {})

    def _screen_job(self, cfg, mode):
        U = self.call_ui
        if not U(lambda: bool(self.screen_view.get() or self.screen_ctl.get())):
            ok = U(lambda: messagebox.askyesno("Экран", "Отправить снимок экрана модели в LM Studio?"), timeout=60)
            if not ok:
                return ("say", "Хорошо, на экран не смотрю.")
        self.avatar_event("tool", name="screenshot")
        self.set_status("Смотрю на экран…")
        shot = self._grab(dict(cfg, grid=False))
        self.append("📷", f"скриншот {shot['size'][0]}×{shot['size'][1]} отправлен модели", "tool")
        if mode == "translate":
            q = ("Найди на скриншоте основной текст не на русском языке и переведи его на русский. "
                 "Если такого текста нет — так и скажи.")
        else:
            q = ("Посмотри на скриншот и кратко объясни, что сейчас на экране и чем занят пользователь "
                 "(2–4 предложения). Координаты и размеры не называй.")
        return ("llm", q, {"shot": shot})

    # ---------- 8. диктовка ----------
    def _dict_changed(self):
        on = bool(self.dictating.get())
        if on:
            self._dict_last = None
        try:
            self.root.title("Nightlord агент — ✍ ДИКТОВКА" if on else "Nightlord агент")
        except Exception:
            pass

    def _on_dict_toggle(self):
        if not self.dictating.get():
            return
        try:
            import pynput  # noqa: F401
        except ImportError:
            self.dictating.set(False)
            messagebox.showinfo("Диктовка", "Нужен пакет pynput:\npy -3.12 -m pip install pynput")
            return
        if not messagebox.askokcancel(
                "Диктовка",
                "Всё, что вы скажете, будет печататься в окно, которое сейчас активно (как с клавиатуры).\n\n"
                "• Остановить: скажите «закончи диктовку», снимите эту галочку или пункт в меню трея.\n"
                "• Чтобы текст попал не в окно агента, не нажимайте его кнопки: используйте режим «Автоматически "
                "по голосу».\n• Отменить напечатанное: «отмени последнее действие».\n\nВключить?"):
            self.dictating.set(False)
            return
        if not self.listening:
            self.set_status("Диктовка включена, но микрофон не слушает: нажмите «Слушать» (режим VAD)")

    def _dict_toggle(self):
        self.dictating.set(not self.dictating.get())

    def _dict_begin(self):
        U = self.call_ui
        ok = U(lambda: messagebox.askyesno(
            "Диктовка", "Печатать всё сказанное в активное окно?\nСтоп: «закончи диктовку»."), timeout=60)
        if not ok:
            return ("say", "Хорошо, диктовку не включаю.")
        U(lambda: self.dictating.set(True))
        return ("say", "Диктую. Чтобы закончить, скажите: закончи диктовку.")

    def _dict_type(self, s):
        keyboard, mouse, kb, ms = self._controllers()
        self._check_failsafe()
        parts = s.split("\n")
        for i, p in enumerate(parts):
            if p:
                kb.type(p)
            if i < len(parts) - 1:
                kb.press(keyboard.Key.enter)
                kb.release(keyboard.Key.enter)
        self.log_action("dictation", {"chars": len(s)}, "напечатано", ("backspace", len(s)))

    def _dictate(self, cfg, text):
        """Обрабатывает фразу в режиме диктовки. Возвращает фразу для озвучки или None."""
        if DICT_STOP_RE.match(norm_ru(text)):
            self.call_ui(lambda: self.dictating.set(False))
            self.append("✍", "диктовка выключена", "tool")
            return "Диктовка выключена."
        s, last = dictation_text(text, self._dict_last)
        if not s:
            return None
        try:
            self._dict_type(s)
        except ImportError:
            self.call_ui(lambda: self.dictating.set(False))
            return "Для диктовки нужен pynput."
        except Exception as e:
            self.call_ui(lambda: self.dictating.set(False))
            self.append("Ошибка", f"диктовка остановлена: {e}", "sys")
            return "Диктовка остановлена."
        self._dict_last = last
        self.append("✍", s.strip() or "⏎", "tool")
        self.avatar_event("gesture", name="type")
        return None

    # ---------- 10. сценарии ----------
    def _macro_voice(self, cfg, name_said):
        macros = load_dict_or_create(MACROS_FILE, DEFAULT_MACROS)
        best = find_profile(name_said, list(macros))
        if not best:
            names = ", ".join(macros) or "пока нет"
            return ("say", f"Не нашла сценарий «{name_said}». Есть: {names}.")
        return self.run_macro(cfg, best)

    def run_macro(self, cfg, name):
        """Выполняет сценарий (из рабочего потока). Возвращает ("say", текст) или ("llm", вопрос, {})."""
        U = self.call_ui
        macros = load_dict_or_create(MACROS_FILE, DEFAULT_MACROS)
        steps = parse_macro(macros.get(name, ""))
        if not steps:
            return ("say", f"Сценарий «{name}» пуст.")
        risky = [s for s in steps if s["type"] in ("app", "url")]
        if risky and cfg.get("macro_confirm", True):
            lines = "\n".join("• " + (f"запустить «{s['name']}»" if s["type"] == "app" else f"открыть {s['url']}")
                              for s in risky)
            if not U(lambda: messagebox.askyesno("Сценарий", f"Сценарий «{name}» хочет:\n\n{lines}\n\nРазрешить?"),
                     timeout=120):
                return ("say", "Сценарий отменён.")
        g0 = self.gen
        quiet = dict(cfg, tools_confirm=False)
        said, ask, fails = [], None, []
        apps = list(load_dict_or_create(APPS_FILE, DEFAULT_APPS))
        for i, s in enumerate(steps, 1):
            if self.gen != g0:
                return ("silent", None)
            t = s["type"]
            self.append("▶", f"{name}: шаг {i}/{len(steps)} — {t}", "tool")
            try:
                if t == "app":
                    nm = find_profile(s["name"], apps) or s["name"]
                    r = str(self.run_tool(quiet, "open_app", {"name": nm}))
                    if "запущена" not in r:
                        fails.append(f"«{s['name']}»: {r[:80]}")
                elif t == "url":
                    r = str(self.run_tool(quiet, "open_url", {"url": s["url"]}))
                    if "открыта" not in r:
                        fails.append(r[:80])
                elif t == "volume":
                    U(lambda v=s["value"]: self.volume.set(v))
                elif t == "mode":
                    r = self._hot_run(cfg, "mode", s["name"], "")
                    if r is None:
                        fails.append(f"режим «{s['name']}» не найден")
                elif t == "tts":
                    U(lambda on=s["on"]: self.speak_on.set(on))
                elif t == "say":
                    said.append(s["text"])
                elif t == "wait":
                    end = time.time() + s["seconds"]
                    while time.time() < end and self.gen == g0:
                        time.sleep(0.1)
                elif t == "ask":
                    ask = ask or s["text"]
                else:
                    fails.append(f"не понял строку «{s['text'][:40]}»")
            except Exception as e:
                fails.append(str(e)[:80])
        if ask:
            for line in said:
                self.append("Агент", line, "bot")
            return ("llm", ask, {})
        out = " ".join(said) or f"Сценарий «{name}» выполнен."
        if fails:
            out += " Не удалось: " + "; ".join(fails) + "."
        return ("say", out)

    def run_macro_ui(self, name):
        """Запуск из окна сценариев (кнопка)."""
        cfg = self._make_cfg()

        def work():
            r = self.run_macro(cfg, name)
            if r and r[0] == "say":
                self.say_direct(r[1])
            elif r and r[0] == "llm":
                self.ui(self.start_pipeline, None, r[1], None)
        threading.Thread(target=work, daemon=True).start()

    def edit_macros(self):
        macros = load_dict_or_create(MACROS_FILE, DEFAULT_MACROS)
        win = tk.Toplevel(self.root)
        win.title("Сценарии")
        win.geometry("620x520")
        ttk.Label(win, text=("Сценарий — список шагов, по одному в строке. Запуск голосом: «сценарий <название>».\n"
                             "Шаги: открыть <программа из белого списка> • открыть сайт https://… • громкость 60 • "
                             "режим <название> • озвучка выкл/вкл • сказать <фраза> • ждать 2 • спросить <вопрос модели>. "
                             "Строка с # — комментарий. Если есть «спросить», фразы «сказать» только пишутся в чат."),
                  wraplength=580, justify="left", foreground="#777").pack(anchor="w", padx=10, pady=(8, 2))
        top = ttk.Frame(win)
        top.pack(fill="x", padx=10, pady=2)
        ttk.Label(top, text="Название:").pack(side="left")
        cur = tk.StringVar(value=next(iter(macros), ""))
        combo = ttk.Combobox(top, textvariable=cur, values=list(macros), width=34)
        combo.pack(side="left", padx=6)
        t = scrolledtext.ScrolledText(win, height=14, wrap="word")
        t.pack(fill="both", expand=True, padx=10, pady=4)
        t.insert("1.0", macros.get(cur.get(), ""))

        def load(*a):
            t.delete("1.0", "end")
            t.insert("1.0", macros.get(cur.get(), ""))

        def save():
            name = cur.get().strip()
            if not name:
                messagebox.showinfo("Сценарии", "Введите название сценария.")
                return False
            macros[name] = t.get("1.0", "end").strip()
            save_json(MACROS_FILE, macros)
            combo["values"] = list(macros)
            self.set_status(f"Сценарий «{name}» сохранён")
            return True

        def delete():
            if macros.pop(cur.get().strip(), None) is not None:
                save_json(MACROS_FILE, macros)
                combo["values"] = list(macros)
                cur.set(next(iter(macros), ""))
                load()
        combo.bind("<<ComboboxSelected>>", load)
        bar = ttk.Frame(win)
        bar.pack(fill="x", padx=10, pady=8)
        ttk.Button(bar, text="Сохранить", command=save).pack(side="left")
        ttk.Button(bar, text="Удалить", command=delete).pack(side="left", padx=6)
        ttk.Button(bar, text="▶ Выполнить сейчас",
                   command=lambda: save() and self.run_macro_ui(cur.get().strip())).pack(side="left")
        ttk.Button(bar, text="Закрыть", command=win.destroy).pack(side="right")

    # ---------- 14. резервная копия ----------
    def do_backup(self):
        try:
            self.save_settings()
        except Exception:
            pass
        dest = filedialog.asksaveasfilename(
            title="Сохранить резервную копию", defaultextension=".zip",
            initialfile=f"nightlord_backup_{datetime.now():%Y%m%d_%H%M}.zip", filetypes=[("ZIP", "*.zip")])
        if not dest:
            return
        secrets = messagebox.askyesno("Резервная копия", "Включить ключи, токены, пароли и ссылки подписок?\n\n"
                                      "Да — для переноса на свой ПК (копию храните как пароль).\n"
                                      "Нет — можно безопасно показать или отправить другому человеку.")
        try:
            n = backup_make(dest, secrets)
            messagebox.showinfo("Резервная копия", f"Сохранено файлов: {n}\n{dest}")
        except Exception as e:
            messagebox.showerror("Резервная копия", str(e))

    def do_restore(self):
        src = filedialog.askopenfilename(title="Восстановить из копии", filetypes=[("ZIP", "*.zip")])
        if not src:
            return
        if not messagebox.askyesno("Восстановление",
                                   "Настройки, промты, профили, память, напоминания, сценарии и настройки плагинов "
                                   "будут заменены из копии (старые файлы сохранятся как *.bak).\n\nПродолжить?"):
            return
        try:
            done = backup_restore(src)
        except Exception as e:
            messagebox.showerror("Восстановление", str(e))
            return
        self._skip_save = True   # иначе при закрытии текущие настройки перезапишут восстановленные
        messagebox.showinfo("Восстановление", f"Восстановлено файлов: {len(done)}.\n"
                                              "Закройте агента и запустите заново — тогда всё применится.")

    # ---------- обновление из файла ----------
    def do_update_file(self):
        if getattr(sys, "frozen", False):
            messagebox.showinfo("Обновление", "Это собранный exe: заменить его изнутри нельзя. "
                                              "Пересоберите exe из нового voice_agent.py (py build_exe.py).")
            return
        src = filedialog.askopenfilename(title="Файл обновления: архив .zip или voice_agent.py",
                                         filetypes=[("Обновление", "*.zip *.py"), ("Все файлы", "*.*")])
        if not src:
            return
        self._update_offer(update_inspect(src))

    def check_github_update(self, auto=False):
        """Скачивает ветку из GitHub в фоне и предлагает обновиться, если версия новее (авто — только если новее)."""
        if getattr(sys, "frozen", False):
            if not auto:
                messagebox.showinfo("Обновление", "Это собранный exe: пересоберите его из нового voice_agent.py.")
            return
        repo, branch, token = self.upd_repo.get().strip(), self.upd_branch.get().strip() or "main", self.upd_token.get().strip()
        if not repo:
            if not auto:
                messagebox.showinfo("Обновление", "Укажите репозиторий GitHub в виде «владелец/имя».")
            return
        if getattr(self, "_upd_busy", False):
            return
        self._upd_busy = True
        self.status.set("Проверяю обновления на GitHub…")

        def work():
            try:
                path = update_download(repo, branch, token)
                info = update_inspect(path)
                try:
                    Path(path).unlink()
                except OSError:
                    pass
                err = None
            except RuntimeError as e:
                info, err = None, str(e)
            self.ui(lambda: self._github_done(info, err, auto))
        threading.Thread(target=work, daemon=True).start()

    def _github_done(self, info, err, auto):
        self._upd_busy = False
        self.upd_last.set(datetime.now().strftime("%Y-%m-%d"))
        if err or info.get("error"):
            self.status.set("Обновление: " + (err or info["error"]))
            if not auto:
                messagebox.showerror("Обновление", err or info["error"])
            return
        newer = ver_key(info["version"]) > ver_key(APP_VERSION)
        if auto and not newer:
            self.status.set("Обновлений нет")
            return
        if not newer and not auto:
            same = False
            try:
                same = hashlib.sha256((BASE / "voice_agent.py").read_bytes()).digest() == hashlib.sha256(info["code"]).digest()
            except OSError:
                pass
            if same or ver_key(info["version"]) == ver_key(APP_VERSION):
                self.status.set(f"Обновлений нет: на GitHub та же версия {info['version']}")
                messagebox.showinfo("Обновление", f"Обновлений нет. Установлена {APP_VERSION}, на GitHub {info['version']}.")
                return
        self._update_offer(info)

    def _update_offer(self, info):
        if info.get("error"):
            messagebox.showerror("Обновление", info["error"])
            return
        cur, new = APP_VERSION, info["version"]
        try:
            same = hashlib.sha256((BASE / "voice_agent.py").read_bytes()).digest() == hashlib.sha256(info["code"]).digest()
        except OSError:
            same = False
        if same:
            messagebox.showinfo("Обновление", f"Это та же версия, что уже установлена ({cur}).")
            return
        note = ""
        if ver_key(new) and ver_key(cur) and ver_key(new) < ver_key(cur):
            note = "\n\nВНИМАНИЕ: файл СТАРШЕ установленной версии."
        elif new == cur:
            note = "\n\nНомер версии тот же, но содержимое отличается."
        extra = ("\nТакже заменятся: " + ", ".join(sorted(info["extras"]))) if info["extras"] else ""
        if not messagebox.askyesno("Обновление", f"Установлена версия {cur}, в файле {new}.{note}{extra}\n\n"
                                   "Старый voice_agent.py сохранится как voice_agent.py.bak, настройки не изменятся. "
                                   "Обновляйте только файлом, которому доверяете: он запускается как программа.\n\nОбновить?"):
            return
        try:
            self.save_settings()
        except Exception:
            pass
        try:
            done = update_apply(info)
        except OSError as e:
            messagebox.showerror("Обновление", f"Не удалось записать файлы: {e}")
            return
        self.status.set(f"Обновлено до {new}: {', '.join(done)}")
        if messagebox.askyesno("Обновление", "Готово. Перезапустить агента сейчас?\n\n"
                                              "Встроенные плагины обновятся сами при запуске (кроме тех, что вы правили); "
                                              "плагины, которые уже были включены, возможно, придётся включить заново."):
            self.restart_self()

    def restart_self(self):
        """Запускает новую копию агента после небольшой паузы (чтобы освободились порты) и закрывает эту."""
        script = str(Path(sys.argv[0] if sys.argv and sys.argv[0] else BASE / "voice_agent.py").resolve())
        helper = "import time,subprocess,sys;time.sleep(3);subprocess.Popen([sys.executable]+sys.argv[1:])"
        try:
            subprocess.Popen([sys.executable, "-c", helper, script] + sys.argv[1:], cwd=str(BASE))
        except OSError as e:
            messagebox.showerror("Перезапуск", f"Не удалось перезапустить: {e}\nЗапустите агента вручную.")
            return
        self.tray_on.set(False)
        self.quit_app()

