    # ---------- вкладка «Мониторинг» ----------
    def _build_monitor(self, p):
        pad = {"padx": 6, "pady": 4}

        f = LabelFrame(p, text="Ресурсы системы", open=True)
        f.pack(fill="x", **pad)
        self.bars = {}
        for i, (key, title) in enumerate([("cpu", "CPU"), ("ram", "RAM"), ("gpu", "GPU"), ("vram", "VRAM")]):
            ttk.Label(f, text=title, width=6).grid(row=i, column=0, sticky="w", **pad)
            pb = ttk.Progressbar(f, maximum=100, length=360)
            pb.grid(row=i, column=1, **pad)
            var = tk.StringVar(value="—")
            ttk.Label(f, textvariable=var, width=52).grid(row=i, column=2, sticky="w", **pad)
            self.bars[key] = (pb, var)

        f2 = ttk.Frame(p)
        f2.pack(fill="x", **pad)
        ttk.Label(f2, text="Интервал опроса, с").pack(side="left")
        self.interval = tk.DoubleVar(value=self._interval)
        ttk.Spinbox(f2, from_=0.5, to=30, increment=0.5, textvariable=self.interval, width=5).pack(side="left", padx=6)
        ttk.Button(f2, text="🩺 Проверить всё", command=self.run_selftest).pack(side="right")
        self.interval.trace_add("write", self._sync_interval)

