    # ---------- аватар ----------
    def avatar_event(self, kind, **kw):
        """Безопасно из любого потока: передаёт событие аватару (если он открыт)."""
        if kind == "gesture" and not self._gest_on:
            return
        if self.avatar.is_open:
            self.ui(self.avatar.handle, kind, kw)
        if self.avatar3d.is_open:
            self.ui(self.avatar3d.handle, kind, kw)
        if self._gest_on and (self.avatar.is_open or self.avatar3d.is_open):
            g = None
            if kind in ("user_said", "speak"):
                g = guess_gesture(kw.get("text", ""))
            elif kind == "tool" and kw.get("name") in ("type_text", "press_key"):
                g = "type"
            if g:
                self.avatar_event("gesture", name=g)

    def _avatar_styles(self):
        names = []
        if AVATAR_DIR.is_dir():
            names = sorted(d.name for d in AVATAR_DIR.iterdir() if d.is_dir())
        return [AVATAR_BUILTIN] + names

    def _refresh_avatar_styles(self):
        self.avatar_style_combo.config(values=self._avatar_styles())
        if self.avatar_style.get() not in self._avatar_styles():
            self.avatar_style.set(AVATAR_BUILTIN)

    def _open_avatar_dir(self):
        AVATAR_DIR.mkdir(exist_ok=True)
        readme = AVATAR_DIR / "README.txt"
        if not readme.exists():
            readme.write_text(
                "Свой аватар (спрайты)\n"
                "=====================\n"
                "1. Создайте здесь папку с любым именем, например  my_cat\n"
                "2. Положите в неё PNG-картинки с прозрачным фоном (желательно одного размера):\n"
                "     idle.png       — обычное состояние (ОБЯЗАТЕЛЬНО)\n"
                "     happy.png, sad.png, angry.png, surprised.png, thinking.png  — эмоции\n"
                "     listening.png  — слушает,  speaking.png — рот открыт (чередуется с эмоцией при речи)\n"
                "     sleeping.png   — спит\n"
                "   Недостающие файлы заменяются на idle.png.\n"
                "3. На вкладке «Аватар» нажмите ⟳ и выберите папку в списке «Внешний вид».\n"
                "Для плавного масштабирования установите Pillow:  py -3.12 -m pip install pillow\n",
                encoding="utf-8")
        try:
            os.startfile(str(AVATAR_DIR))
        except AttributeError:
            webbrowser.open(AVATAR_DIR.as_uri())
        self._refresh_avatar_styles()

    def _on_avatar_toggle(self):
        if self.avatar_on.get():
            try:
                self.avatar.open()
            except Exception as e:
                self.avatar_on.set(False)
                messagebox.showerror("Аватар", f"Не удалось открыть окно аватара:\n{e}")
        else:
            self.avatar.close()

    # ---------- 3D-аватар: управление ----------
    def _refresh_3d_models(self):
        vals = [AVATAR3D_BUILTIN] + Avatar3D.models()
        self.avatar3d_model_combo.config(values=vals)
        if self.avatar3d_model.get() not in vals:
            self.avatar3d_model.set(AVATAR3D_BUILTIN)

    def _push_3d_cfg(self, *a):
        if self.avatar3d.is_open:
            self.avatar3d.refresh_cfg()

    def _on_avatar3d_toggle(self):
        if self.avatar3d_on.get():
            port = self._num(self.avatar3d_port, 8765)
            try:
                self.avatar3d.open(port)
            except OSError as e:
                self.avatar3d_on.set(False)
                messagebox.showerror("3D-аватар", f"Не удалось запустить сервер на порту {port}:\n{e}\n\n"
                                                  f"Укажите другой порт и включите снова.")
                return
            self.avatar3d_url.set(self.avatar3d.url())
            self.status.set(f"3D-аватар: {self.avatar3d.url()} (кнопка «Открыть окно аватара»)")
        else:
            self.avatar3d.close()
            self.avatar3d_url.set("")

    def _open_3d_dir(self):
        AVATAR3D_DIR.mkdir(exist_ok=True)
        readme = AVATAR3D_DIR / "README.txt"
        if not readme.exists():
            readme.write_text(AVATAR3D_README, encoding="utf-8")
        try:
            os.startfile(str(AVATAR3D_DIR))
        except AttributeError:
            webbrowser.open(AVATAR3D_DIR.as_uri())
        self._refresh_3d_models()

    @staticmethod
    def _find_browser():
        for n in ("msedge", "chrome", "google-chrome", "chromium"):
            w = shutil.which(n)
            if w:
                return w
        for key in ("ProgramFiles", "ProgramFiles(x86)", "LocalAppData"):
            base = os.environ.get(key)
            if not base:
                continue
            for rel in (r"Microsoft\Edge\Application\msedge.exe", r"Google\Chrome\Application\chrome.exe"):
                c = Path(base) / rel
                if c.exists():
                    return str(c)
        return None

    def _open_3d_window(self):
        if not self.avatar3d.is_open:
            self.avatar3d_on.set(True)
            self._on_avatar3d_toggle()
            if not self.avatar3d.is_open:
                return
        url = self.avatar3d.url()
        exe = self._find_browser()
        try:
            if exe:  # окно без вкладок и адресной строки
                subprocess.Popen([exe, f"--app={url}", "--window-size=480,760"])
                return
        except OSError:
            pass
        webbrowser.open(url)

    def _copy_3d_url(self):
        url = self.avatar3d.url(obs=True)
        self.root.clipboard_clear()
        self.root.clipboard_append(url)
        self.status.set(f"Адрес для OBS скопирован: {url}")

    def _avatar_test(self, kind):
        if not self.avatar.is_open and not self.avatar3d.is_open:
            self.avatar_on.set(True)
            self._on_avatar_toggle()
        targets = [x for x in (self.avatar, self.avatar3d) if x.is_open]
        for av in targets:
            if kind in EMOTION_NAMES:
                av.handle("emotion", {"name": kind})
            elif kind == "speak":
                n = 60
                env = np.clip(np.abs(np.sin(np.arange(n) * .8)) * np.random.uniform(.5, 1, n), 0, 1)
                av.handle("speak", {"env": env, "dur": n * ENV_DT, "emotion": "happy",
                                    "text": "Привет! Я ваш голосовой помощник."})
            elif kind == "sleep":
                if av is self.avatar:
                    av.state = "sleeping"
                else:
                    av.handle("sleep", {})
            elif kind == "tool":
                av.handle("tool", {"name": "screenshot"})
            elif kind == "error":
                av.handle("error", {"text": "тестовая ошибка"})
            elif kind == "listen":
                av.handle("listening", {})

